const h=[{id:"c1",title:"第一章 · 红袖章",sub:"她记名字的时候不看人",photo:"campus-day",beats:[{t:"scene",photo:"campus-day",place:"教学楼东侧楼梯",time:"第三节课前",x:"楼梯间有洗衣粉和旧木头的味道。"},{t:"narr",x:"第三节课上课前，你在楼梯口被叫住了。"},{t:"say",who:"沈砚",x:"同学，麻烦过来一下。"},{t:"narr",x:"她左臂上那个红袖章别得很正，袖口压得一丝不苟。"},{t:"narr",x:"手里是一本黑色硬壳本子，翻到夹着便签的那一页。"},{t:"say",who:"沈砚",x:"十月二十八号，晚自习后，东侧楼梯，两个人。其中一个是你吧。"},{t:"narr",x:"楼梯间的窗户开了一半，风把本子吹得自己翻页，她用手掌压住。"},{t:"choice",q:"她的笔尖悬在纸上，没有抬眼看你。",opts:[{x:"「是我。我们只是顺路。」",aff:12,best:!0,reply:"「顺路。」她把这两个字念了一遍，写下来，加了引号。"},{x:"「你怎么确定的？」",aff:6,reply:"她终于抬头：「因为我在后面跟了半层楼。」"},{x:"「这也要记？」",aff:-8,reply:"「要记。」她翻了一页，「今天已经记了十一页。」"}]},{t:"say",who:"沈砚",x:"三对里面，有一对是从「顺路」开始的。你猜猜他们现在在哪儿。"},{t:"me",x:"……在家？"},{t:"say",who:"沈砚",x:"在办公室。家长在旁边坐着。"},{t:"narr",x:"她把本子合上，声音低了一点，不像刚才那么公事公办。"},{t:"say",who:"沈砚",x:"我不想记满一整本。你明白我意思吧。"},{t:"choice",q:"她这话说得有点奇怪。",opts:[{x:"「你也是被派来做这个的。」",aff:14,best:!0,reply:"她顿了一下：「……嗯。年级主任说，女生查女生，男生查男生，我算是被抓壮丁。」"},{x:"「那你能不能划掉？」",aff:7,reply:"「划掉？」她笑了一下，很短，「划掉的东西，主任一眼就能看出来。」"},{x:"「随你记。」",aff:-6,reply:"她重新翻开本子，笔尖压得很重。"}]},{t:"narr",x:"走廊尽头，红色袖章在往这边移动。是另外一个查恋队的人。"},{t:"say",who:"沈砚",x:"……你鞋带开了。"},{t:"narr",x:"你低头看。鞋带好好的，两个圈都系得一样大。"},{t:"choice",q:"她在给你争取时间。",opts:[{x:"蹲下去，把鞋带解开重系。",aff:12,best:!0,reply:"你蹲下的那十几秒，红袖章从你们身边走过去，什么都没说。"},{x:"蹲下去，系得很慢很慢。",aff:5,reply:"红袖章在你们旁边停了两秒。她的手指在本子边上敲了一下，那人又走了。"},{x:"转身往反方向走。",aff:-8,reply:"「站住。」她的声音不大，但你停住了。"}]},{t:"narr",x:"上课铃响了。第三节课是数学，走廊瞬间空了。"},{t:"say",who:"沈砚",x:"……你先去上课。"},{t:"me",x:"那你写什么？"},{t:"say",who:"沈砚",x:"「未发现异常。」"},{t:"narr",x:"她说这四个字的时候，看着本子，没有看你。"},{t:"say",who:"沈砚",x:"对了。你叫什么名字。"},{t:"narr",x:"你报了名字。她在本子最上面那一行写下来，写完又描了一遍。"},{t:"say",who:"沈砚",x:"记住了。下次别让我写第二遍。"},{t:"narr",x:"你上楼的时候回头看了一眼。她还站在原地，袖章在窗光里红得很硬。"},{t:"scene",photo:"campus-day",place:"高二三班后门",time:"午休 12:20",x:"教室里只开了后两排的灯，桌上摊着没收的卷子。"},{t:"narr",x:"午休，你去还她落在楼梯上的笔。一支很旧的黑色中性笔，笔帽上有咬出来的牙印。"},{t:"narr",x:"她坐在最后一排靠窗的位置，本子摊开，正在画格子。"},{t:"say",who:"沈砚",x:"笔放桌上。"},{t:"me",x:"你不问我在哪儿捡的。"},{t:"say",who:"沈砚",x:"问了也没用。"},{t:"narr",x:"本子摊开的那一页画着整齐的方格，格子里填着日期、地点、名字。"},{t:"say",who:"沈砚",x:"你看到多少。"},{t:"me",x:"看到一行。"},{t:"narr",x:"她把本子往怀里挪了半寸，挪完又停住，好像觉得这个动作很难看。"},{t:"say",who:"沈砚",x:"十月二十八号那一行，我还没填。"},{t:"choice",q:"她的手指按在那行空格上。",opts:[{x:"「那就空着。」",aff:13,best:!0,reply:"她看了你两秒，把笔帽扣回去：「……你倒是不怕。」"},{x:"「填了会怎么样？」",aff:5,reply:"「通知家长，写检查，班主任谈话。」她数得很平，「一套流程，三天走完。」"},{x:"「你不是纪检吗，空着算失职吧。」",aff:-8,reply:"她把手收回去：「失职，我认。」"}]},{t:"narr",x:"教室后排有人在笑，声音不大，但两个人都听见了。"},{t:"say",who:"沈砚",x:"他们说我是狗。你听见了吗。"},{t:"me",x:"听见了。"},{t:"say",who:"沈砚",x:"那你为什么还站在这儿。"},{t:"choice",q:"她抬起头，第一次正面看你。",opts:[{x:"「因为你刚才没说我的名字。」",aff:14,best:!0,reply:"她的笔在纸上停住，很久没有动。然后她低下头，把那一行轻轻描了一遍。"},{x:"「我也想知道。」",aff:6,reply:"「我也不知道。」她说，「大概是因为走廊太长，一个人站着很难看。」"},{x:"「其实我也觉得你多管闲事。」",aff:-6,reply:"她把本子合上：「那你可以走了。」"}]},{t:"narr",x:"她低头，在本子空白的地方画了一个很小的方格，又把它涂掉。"},{t:"say",who:"沈砚",x:"你回去吧。下午我要去年级组交表。"},{t:"me",x:"交什么表。"},{t:"say",who:"沈砚",x:"这个月的检查记录。十九个名字。"},{t:"narr",x:"她站起来，把袖章别回左臂。那个动作很熟练，熟练到有点让人难受。"},{t:"say",who:"沈砚",x:"同学。"},{t:"me",x:"嗯？"},{t:"say",who:"沈砚",x:"下次走东侧楼梯，别两个人。"},{t:"narr",x:"她说完就走了，本子夹在腋下，脚步很快，像怕被人追上。"},{t:"tip",x:"主线开始。她的本子第一页，多了你的名字。"}]},{id:"c2",title:"第二章 · 本子里的空行",sub:"她其实留了很多页没写",photo:"campus-aerial",beats:[{t:"scene",photo:"campus-aerial",place:"行政楼天台",time:"午休 12:40",x:"天台上风很大，能看见整个操场。"},{t:"narr",x:"午休，你去天台找一个安静的角落。门没锁，推开的时候，栏杆边站着一个人。"},{t:"say",who:"沈砚",x:"……你怎么上来了。"},{t:"me",x:"我还想问你。"},{t:"narr",x:"她把本子抱在胸前，风把袖章吹得翻起来一角。她伸手按住。"},{t:"say",who:"沈砚",x:"这里没人来。我每天上来十分钟。"},{t:"me",x:"来干什么？"},{t:"say",who:"沈砚",x:"什么都不干。"},{t:"narr",x:"角落里倒扣着一个旧水桶，上面垫了一张卷子，边角压着半块砖。那是她的位置。"},{t:"narr",x:"她顿了一下，把本子翻开，给你看最后几页。整页整页的空白。"},{t:"say",who:"沈砚",x:"前面记了四十七个名字。后面这些，我一个都没写。"},{t:"choice",q:"她把本子递过来。",opts:[{x:"「那四十七个里，有几个是真的？」",aff:12,best:!0,reply:"她想了一会儿：「……大概十个。剩下的都是被同学开玩笑报上来的。」"},{x:"「不写不就行了。」",aff:5,reply:"「不写，主任会自己下来查。」她把本子合上，「我写，至少还能挑。」"},{x:"「你挺会给自己找理由。」",aff:-8,reply:"她的手停在半空，然后把本子收了回去：「是。你说得对。」"}]},{t:"narr",x:"风把她额前的头发吹乱。她没去理，过了很久才说话。"},{t:"say",who:"沈砚",x:"我初一的时候，也被人记过一次。"},{t:"me",x:"记什么？"},{t:"say",who:"沈砚",x:"记「和男生在楼梯间说话超过五分钟」。"},{t:"narr",x:"她说这句话的时候，语速跟平时念通报一样平。"},{t:"say",who:"沈砚",x:"后来我做了纪检。我想，至少这个本子在我手里，我能决定谁被写上去。"},{t:"choice",q:"她说这话的时候，一直看着操场。",opts:[{x:"「那你现在决定，我不写。」",aff:14,best:!0,reply:"她转过头看你，看了很久，然后很轻地笑了一下：「……你这个人，真会挑时候。」"},{x:"「那你把自己也写上去吗？」",aff:7,reply:"「我？」她低头看本子，「我没有可写的。我每天就是查别人。」"},{x:"「所以你是为了自己。」",aff:-6,reply:"她把本子合上：「可能吧。我没想过这么细。」"}]},{t:"narr",x:"操场上有人在跑八百米。跑到最后一圈，看台上有人喊了一声名字。"},{t:"say",who:"沈砚",x:"我记过一个人。女生，高一六班的。"},{t:"me",x:"记她什么。"},{t:"say",who:"沈砚",x:"记她晚自习后在小花园待了二十分钟。其实她在那儿背单词，那地方路灯最亮。"},{t:"narr",x:"她说到这里停了，把本子翻到中间那一页，指给你看。"},{t:"narr",x:"那一行被划掉了。划得很轻，只划了一道，名字还看得清。"},{t:"say",who:"沈砚",x:"我划的。主任没看出来。"},{t:"choice",q:"她的指甲在那道横线上停着。",opts:[{x:"「那你划的时候，手抖了吗。」",aff:13,best:!0,reply:"「抖了。」她说得很干脆，「第一笔还画歪了，我又补了一道。」"},{x:"「你这样很危险。」",aff:6,reply:"「我知道。」她把那一页翻过去，「所以这一页我从来不给人看。」"},{x:"「你这是徇私。」",aff:-8,reply:"她点头：「是。」然后她把本子按在胸口：「你要去说吗。」"}]},{t:"narr",x:"天台的铁门在下面响了一声，有人在推门。"},{t:"say",who:"沈砚",x:"蹲下。"},{t:"narr",x:"你们蹲在水桶后面。风把摊开的本子吹得哗哗响。"},{t:"narr",x:"进来的是扫地阿姨，拎着一个红水桶，把拖把往池子里一放，又出去了。"},{t:"say",who:"沈砚",x:"她每天这个点来。我忘了。"},{t:"me",x:"你也会有忘的时候。"},{t:"say",who:"沈砚",x:"会。忘得越来越多。"},{t:"narr",x:"她站起来，膝盖上沾了一块灰，拍了三下才拍掉。"},{t:"say",who:"沈砚",x:"你为什么不问我，为什么留这么多空页。"},{t:"me",x:"我在等你说。"},{t:"narr",x:"她笑了一下，很轻，转过去看操场。"},{t:"say",who:"沈砚",x:"因为写满了，本子就要交上去存档。空着，它就还是我的。"},{t:"choice",q:"她把本子举起来，对着光看那些空白页。",opts:[{x:"「那就一直空着。写到毕业。」",aff:15,best:!0,reply:"她没说话，把本子放下来的时候，手指在封面上按了一下。"},{x:"「交上去会怎么样。」",aff:6,reply:"「装订，编号，进档案室。」她说，「以后谁想看都能看。」"},{x:"「本子是你的，名字是别人的。」",aff:-6,reply:"她的表情变了一下：「我知道。所以我记得很慢。」"}]},{t:"narr",x:"下课铃从楼下传上来，隔着一层风，听起来很远。"},{t:"scene",photo:"campus-aerial",place:"教学楼二楼楼梯间",time:"午休 13:05",x:"走廊里全是粉笔灰和刚拖过的水痕。"},{t:"say",who:"沈砚",x:"还有三分钟上课。你先走。"},{t:"me",x:"为什么？"},{t:"say",who:"沈砚",x:"因为我现在没戴袖章。"},{t:"narr",x:"她把袖章从口袋里拿出来，慢慢别回左臂上。那个动作很熟练，熟练到有点让人难受。"},{t:"narr",x:"走到二楼，她忽然停住，从本子上撕下一页，折了两折，塞进你校服口袋。"},{t:"me",x:"这是什么。"},{t:"say",who:"沈砚",x:"空白的。你自己写。"},{t:"choice",q:"她按住你的口袋，没有松手。",opts:[{x:"「我写什么都可以？」",aff:14,best:!0,reply:"「都可以。」她把手收回去，「写完自己留着，别给我看。」"},{x:"「你不怕我写你。」",aff:6,reply:"「写吧。」她说，「写完记得撕。」"},{x:"「我不需要你的施舍。」",aff:-8,reply:"她把手收回去，退了半步：「好。是我多事。」"}]},{t:"narr",x:"楼梯间的灯闪了一下。她松开手，往楼上走，走了两步又回头。"},{t:"say",who:"沈砚",x:"还有。以后别站在天台门口，风大。"},{t:"narr",x:"她上楼以后，你摸了一下口袋。那页纸很薄，边缘撕得不齐。"},{t:"tip",x:"第二章结束。她撕给你的那一页，你一直没写。"}]},{id:"c3",title:"第三章 · 广播之后",sub:"全校都听见了，除了她",photo:"stage",beats:[{t:"scene",photo:"stage",place:"操场 · 主席台后",time:"周五 16:10",x:"运动会彩排，主席台的音箱在试音。"},{t:"narr",x:"周五下午彩排。你被拉去搬椅子，搬完坐在主席台后面的台阶上。"},{t:"narr",x:"广播忽然响了。开头那一声电流响，不是试音。"},{t:"say",who:"广播",x:"……下面播报一则通报。近期校园恋爱专项检查中，仍有同学在课间走廊并排同行。"},{t:"narr",x:"你听见自己的名字，被念了出来。念得很标准，一个字都没错。"},{t:"narr",x:"台下有人回头。你坐在原地，手上还沾着椅子的灰。"},{t:"me",x:"（念稿的是沈砚。她的声音从音箱里出来，有点变形。）"},{t:"narr",x:"通报念了两分半。第二个名字是隔壁班的男生，第三个名字念到一半，停了一拍。"},{t:"say",who:"广播",x:"以上。请相关同学到年级组说明情况。"},{t:"narr",x:"音箱的底噪消失那一秒，整个操场很安静。"},{t:"narr",x:"广播室里，沈砚站在话筒前，手里捏着那张稿纸。她念完了，把话筒推远。"},{t:"say",who:"沈砚",x:"……不是我写的。"},{t:"me",x:"我知道。"},{t:"say",who:"沈砚",x:"主任让我念。我不念，他就换别人念。"},{t:"narr",x:"她的手指在抖。稿纸被捏出一道白痕。"},{t:"choice",q:"她的手指在抖。",opts:[{x:"「那就换别人念。你别念。」",aff:12,best:!0,reply:"她看着你，眼睛红了一下，又压回去：「……好。下次我撕了它。」"},{x:"「念都念了，还能怎么办。」",aff:6,reply:"她把稿纸折起来，折成很小的一块，塞进口袋。"},{x:"「你是不是也觉得我活该。」",aff:-8,reply:"「我没有。」她说得很快，「我从来没有这么想过。」"}]},{t:"narr",x:"广播室的窗朝西，下午的光斜进来，落在调音台那一排推子上。"},{t:"say",who:"沈砚",x:"稿子是年级组写的。落款是我的名字，因为我是队长。"},{t:"me",x:"落款？"},{t:"narr",x:"她把稿纸翻过来。右下角一行打印的字，后面跟着她的名字。"},{t:"say",who:"沈砚",x:"我不签，他们也可以印。"},{t:"narr",x:"她把稿纸折起来，又展开，最后塞进了口袋。"},{t:"choice",q:"她背对着你，肩膀绷得很紧。",opts:[{x:"「那你就摘了袖章，去台上说清楚。」",aff:13,best:!0,reply:"她转过身，看了你很久：「说了以后，我就不用再念稿子了。」"},{x:"「去找主任解释。」",aff:5,reply:"她摇头：「解释要写材料，材料要家长签字。」"},{x:"「你早该想到会有今天。」",aff:-6,reply:"「我早就想到了。」她说，「我只是没想到会念到你的名字。」"}]},{t:"narr",x:"楼下有人在喊她的名字。是学生会的，催她去主席台领队形表。"},{t:"say",who:"沈砚",x:"等我十分钟。"},{t:"narr",x:"她下楼没走楼梯，直接跑下去的。帆布鞋在楼道里响了很久。"},{t:"scene",photo:"stage",place:"操场 · 主席台侧",time:"周五 16:50",x:"彩排散了，音箱还带着电，嗡嗡地响。"},{t:"narr",x:"彩排散了。台上的人一排一排下来，椅子一排一排空着。"},{t:"narr",x:"你在主席台侧边等到天开始暗。她从那头走过来，左臂上是空的。"},{t:"say",who:"沈砚",x:"我退队了。"},{t:"me",x:"这么快？"},{t:"say",who:"沈砚",x:"表格要三个人签字。我找了三个人。"},{t:"narr",x:"她把一张复印件给你看。主任的签名在最下面，笔尖把纸戳破了一点。"},{t:"say",who:"沈砚",x:"他签的时候说，你想清楚，以后评优评先没有你。"},{t:"me",x:"你怎么说。"},{t:"say",who:"沈砚",x:"我说我知道。"},{t:"choice",q:"她说话的时候，看着主席台上那排还没收的椅子。",opts:[{x:"「那你还站在这里干什么。」",aff:14,best:!0,reply:"「等你。」她说，就两个字，说完自己先别过脸去。"},{x:"「以后怎么办。」",aff:7,reply:"「以后的事以后再说。」她想了想，「这句话我以前从来没说过。」"},{x:"「为了我，值吗。」",aff:-8,reply:"她皱起眉：「你别把自己放这么重。」"}]},{t:"narr",x:"广播室的音箱忽然又响了一下，是试音的电流声，很短。"},{t:"say",who:"沈砚",x:"我今天在话筒前站了很久。念到你的名字，我想把稿子撕了。"},{t:"me",x:"那你为什么没撕。"},{t:"say",who:"沈砚",x:"因为广播室里还站着两个人。"},{t:"narr",x:"她说到这里停住，抬手把头发别到耳后。手腕上是空的。"},{t:"narr",x:"散场以后，操场上只剩一排一排的空椅子。她走过来，把一样东西放在你手里。"},{t:"narr",x:"是那本黑色硬壳本子。封面上有一道被压出来的折痕。"},{t:"say",who:"沈砚",x:"给你。"},{t:"me",x:"那你呢？"},{t:"say",who:"沈砚",x:"我不查了。"},{t:"narr",x:"她说得很轻，像在说一件跟自己无关的事。"},{t:"choice",q:"本子比上次沉了一点。",opts:[{x:"「本子给我了，你留什么。」",aff:13,best:!0,reply:"「我留空的。」她把两只手插进校服口袋，「第一次不用写东西。」"},{x:"「里面还有空页吗。」",aff:6,reply:"「有。很多。」她顿了一下，「我不打算再填了。」"},{x:"「这就是你的道歉？」",aff:-6,reply:"她抬眼看你，很慢地说：「不是道歉。是交底。」"}]},{t:"say",who:"沈砚",x:"本子最后一页，我写了你的名字。不是记名字那种写。"},{t:"narr",x:"你翻开最后一页。那一页的字迹比前面所有页都慢："},{t:"narr",x:"本子最下面那一行，只有一句：「今天起，我申请退出纪检。」"},{t:"narr",x:"那一行下面还有一行更小的字：本子留给沈砚以外的人保管。"},{t:"choice",q:"她站在空操场中间等你说话。",opts:[{x:"「那我申请，以后跟你一起走。」",aff:16,best:!0,reply:"她愣了很久，久到操场另一头的灯都亮了。然后她伸手，把你手里那本本子拿了回去，抱在怀里：「……这句我记下了。」"},{x:"「你确定吗？这会很麻烦。」",aff:7,reply:"「我知道。」她把袖章摘下来，叠好，「麻烦的事我做过很多。这次我想做一件不麻烦的。」"},{x:"把本子还给她，什么也没说。",aff:-10,reply:"她接过本子，点了点头：「嗯。我明白。」"}]},{t:"narr",x:"那天晚上，公告栏上贴了新的通报。第三对的名字被划掉了，旁边盖了一个很小的「已复核」章。"},{t:"narr",x:"没有人知道是谁去复核的。也没有人来问。"},{t:"tip",x:"第三章结束。红袖章收进抽屉，本子换了主人。"}]}],l=[{id:"c1",title:"第一章 · 转学第一天",sub:"她把整间教室画进了一张纸",photo:"cosplay",beats:[{t:"scene",photo:"cosplay",place:"高一（3）班 · 靠窗最后一排",time:"九月，第一节晚自习",x:"窗外的树影落在她的画本上。"},{t:"narr",x:"九月，转学生来的第一天。班主任把她安排在靠窗最后一排，你旁边。"},{t:"narr",x:"她背着画筒进来，校服袖子长出一截，盖住半个手背。"},{t:"say",who:"林晚",x:"……这里有人坐吗。"},{t:"me",x:"没有。"},{t:"narr",x:"她把画筒靠在桌腿边，画本放在桌角，没有打开。"},{t:"narr",x:"整节晚自习她都在看窗外。香樟在动，她的笔在纸上也在动。"},{t:"narr",x:"下课铃响，她起身，画本从桌角滑下去，摊在地上。"},{t:"narr",x:"经过的人停了半秒。纸上是一整间教室，四十六张桌子，四十六个人。"},{t:"narr",x:"最后一排打瞌睡的那个都在，连粉笔槽里那半截粉笔也没落下。"},{t:"choice",q:"她蹲下去捡，你也蹲下去。",opts:[{x:"「你什么时候画的？」",aff:12,best:!0,reply:"「上课的时候。」她把画本抱好，「我记东西的方式跟别人不太一样。」"},{x:"「画得真像。」",aff:5,reply:"「像不算好。」她小声说，「我只是记得住。」"},{x:"帮她一起捡散在地上的炭笔。",aff:6,reply:"她愣了一下，说了声谢谢，把炭笔一根一根数回笔袋。"}]},{t:"narr",x:"她把纸按平，用袖口擦掉边上蹭的灰。"},{t:"say",who:"林晚",x:"我记东西的方式跟别人不太一样。"},{t:"narr",x:"第二天早自习，你的桌上多了一张纸，压在数学卷子下面。"},{t:"narr",x:"是你。侧着脸，手里转着笔，只有轮廓，但一眼认得出。"},{t:"say",who:"林晚",x:"（小声）画得不好，别给别人看。"},{t:"narr",x:"她把脸埋进英语书里，只留一撮头发在书脊上。"},{t:"choice",q:"她说完就把脸埋进书里。",opts:[{x:"「我留着。」把纸夹进课本。",aff:12,best:!0,reply:"她从书后面露出半只眼睛，看了你一会儿，又缩回去。"},{x:"「为什么画我？」",aff:6,reply:"「因为……你转笔的样子很好画。」她说完就后悔了，耳朵更红。"},{x:"「画得一般。」",aff:-8,reply:"她伸手：「那还我。」你把纸举高，她够不到，最后趴在桌上不理你了。"}]},{t:"narr",x:"那节课是语文。老师讲《荷塘月色》，她在画荷叶。"},{t:"narr",x:"你看了半节课的荷叶，也看了半节课她握笔的手。"},{t:"narr",x:"她的手腕很细，炭笔在纸上走得很轻，像怕弄破纸。"},{t:"say",who:"林晚",x:"你一直看，我画不下去。"},{t:"me",x:"（转回课本，耳朵有点热。）"},{t:"narr",x:"午休时班主任让她去美术教室领画具。她站在门口，回头看你。"},{t:"say",who:"林晚",x:"你知道美术教室在哪吗。"},{t:"me",x:"三楼，走廊尽头，原来放杂物那间。"},{t:"narr",x:"她点头，抱着画筒往外走，走到门口又停下。"},{t:"say",who:"林晚",x:"……你能带我去吗。"},{t:"choice",q:"走廊里有人在打闹，拖把桶横在路中间。",opts:[{x:"「走，我带你去。」",aff:10,best:!0,reply:"她抱着画筒跟上来，走得比你慢半步，一直踩在你的影子上。"},{x:"「我也正好要去。」",aff:5,reply:"「那你本来是要去哪。」她问完，自己先笑了。"},{x:"「你自己问人不就行了。」",aff:-6,reply:"她点点头，抱着画筒去问走廊里的男生，很客气，声音很小。"}]},{t:"scene",photo:"campus-day",place:"美术教室 · 三楼尽头",time:"周四，社团活动时间",x:"窗台上摆着上一届留下的石膏像，落了一层灰。"},{t:"narr",x:"门锁着。钥匙挂在门框上方的钩子上，她踮脚也够不到。"},{t:"narr",x:"你伸手取下来。她说了声谢谢，声音被走廊的风吹散。"},{t:"narr",x:"里面堆着画架、旧报纸、几支干掉的颜料。"},{t:"say",who:"林晚",x:"这里很好。"},{t:"me",x:"好在哪里。"},{t:"say",who:"林晚",x:"窗户大。光从上面下来，人的脸会有一半在暗里。"},{t:"narr",x:"她拉开一把椅子坐下，画本摊在膝盖上，抬头看你。"},{t:"say",who:"林晚",x:"你站到窗边去。"},{t:"me",x:"又要画我。"},{t:"say",who:"林晚",x:"这次画整间教室。你站在那里，教室才是满的。"},{t:"narr",x:"你站了很久。走廊有脚步声，有人拖着水桶经过。"},{t:"narr",x:"她画得很快，炭笔沙沙响，偶尔用拇指擦一下纸面。"},{t:"choice",q:"她画到一半，忽然把画本转过来一点。",opts:[{x:"「我在你画的教室里，是第几个？」",aff:12,best:!0,reply:"她用笔尖点着纸数了数：「最后一个。进门那个不是我画的，是你自己走进来的。」"},{x:"「光线真好。」",aff:6,reply:"「嗯。这个时间的光只有二十分钟。」她抬头看了一眼窗框。"},{x:"「你画得比拍照还快。」",aff:-8,reply:"她把画本合了一半，说拍照不用记，按一下就行。"}]},{t:"narr",x:"收工时她把画本合上，纸边被手指蹭出一道灰印。"},{t:"narr",x:"她说这张要交给社团，当作新生的入社作品。"},{t:"say",who:"林晚",x:"我还没报名。"},{t:"me",x:"那就现在报。"},{t:"narr",x:"报名表在讲台上。她把名字写在最后一栏，字很小，笔画很用力。"},{t:"say",who:"林晚",x:"林晚。晚上的晚。"},{t:"scene",photo:"crowd",place:"食堂 · 二楼靠窗",time:"周五中午",x:"窗外的湖面亮得刺眼。"},{t:"narr",x:"周五中午，她端着餐盘站在你对面，站了很久才坐下。"},{t:"narr",x:"餐盘里只有一份青菜和半碗饭，画本压在餐盘边上。"},{t:"say",who:"林晚",x:"这张给你。"},{t:"narr",x:"是那间美术教室。窗边站着一个人，只有背影，头发被光切出一道边。"},{t:"choice",q:"纸角上还有一小块没擦干净的炭灰。",opts:[{x:"「下次画正面吧。我想看看你画的脸。」",aff:14,best:!0,reply:"她捏着筷子没动，过了几秒才说：「那得先有人肯坐正。」"},{x:"「这张比上一张还像。」",aff:8,reply:"她把汤碗往你那边推了推：「汤要凉了。」"},{x:"「我不喜欢背影。」",aff:-10,reply:"她把画收回去，折了两折，压在餐盘下面，一顿饭没再说话。"}]},{t:"narr",x:"她低头吃饭，筷子在碗沿上敲了两下。"},{t:"say",who:"林晚",x:"那就得有人一直站着。"},{t:"me",x:"（她说完没抬头。食堂很吵，只有这一句落得很清楚。）"},{t:"tip",x:"第一天结束，你的课本里多了一张没有署名的纸。"}]},{id:"c2",title:"第二章 · 天台的速写",sub:"她画了整座学校，没有画自己",photo:"lake-dorm",beats:[{t:"scene",photo:"track-aerial",place:"教学楼天台",time:"周三 17:20",x:"夕阳把蓝色跑道照成紫色。"},{t:"narr",x:"周三放学，她抱着画本往楼上走。你跟在后面，她没回头，也没拦你。"},{t:"narr",x:"天台的门开着，铁门被风推得轻轻撞墙。"},{t:"narr",x:"她坐在水塔的影子边上，摊开画本，膝盖并得很紧。"},{t:"say",who:"林晚",x:"这里能看见整个操场。我第一天来就找到了。"},{t:"me",x:"画的什么？"},{t:"say",who:"林晚",x:"学校。"},{t:"narr",x:"画纸上是整座学校：教学楼、跑道、食堂、湖边的宿舍。"},{t:"narr",x:"连校门口那棵歪脖子树都在，树下面还站着一个看不清的人。"},{t:"narr",x:"角落里有一个很小的空白，形状像一个人站着的位置。"},{t:"me",x:"这里为什么不画？"},{t:"say",who:"林晚",x:"……画不好自己。"},{t:"choice",q:"她把炭笔在指间转了一圈。",opts:[{x:"「那我帮你画。」",aff:12,best:!0,reply:"她抬头看你：「你会画画？」「不会。」你说，「但我可以站那儿，你照着画。」"},{x:"「你画得这么好，怎么会画不好自己。」",aff:8,reply:"「画别人只要看。」她说，「画自己要一直看。」"},{x:"「不画也没关系。」",aff:6,reply:"「嗯。」她把画本合上，「反正也没人看。」"}]},{t:"narr",x:"她让你站到栏杆边。你站过去，风把校服吹得鼓起来。"},{t:"say",who:"林晚",x:"别动。"},{t:"narr",x:"她画了很久。太阳落到茶山后面，天从橙色变成灰蓝。"},{t:"say",who:"林晚",x:"好了。"},{t:"narr",x:"画上的人只有一个背影，站在栏杆边，看不见脸。"},{t:"me",x:"为什么是背影？"},{t:"say",who:"林晚",x:"因为背影不用画眼睛。"},{t:"choice",q:"她把画本递给你看。",opts:[{x:"「那下次画正面。我想看看你画的眼睛。」",aff:14,best:!0,reply:"她的手停在纸边上，过了几秒才说：「……那你得先看着我。」"},{x:"「背影也挺好。」",aff:4,reply:"「嗯。」她把画本收回去，声音低了一点。"},{x:"「你是不是不敢看人。」",aff:-10,reply:"她沉默了很久，久到风把纸角吹起来：「……是。」"}]},{t:"narr",x:"风大了，她把画本合上，压在膝盖下面。"},{t:"say",who:"林晚",x:"眼睛最难。画错一点，整张脸就不是那个人了。"},{t:"me",x:"你画过很多人？"},{t:"say",who:"林晚",x:"画过。都不认识。"},{t:"narr",x:"她说这话的时候在看跑道，跑道上有人在一圈一圈地跑。"},{t:"say",who:"林晚",x:"不认识的，画坏了也没关系。"},{t:"me",x:"（原来画背影不是为了好看。）"},{t:"narr",x:"楼下打铃，晚自习预备。她把画筒背上，站起来拍了拍校服。"},{t:"say",who:"林晚",x:"走吧。"},{t:"narr",x:"下到四楼，走廊的灯一盏一盏亮过去，她走在灯和灯之间。"},{t:"choice",q:"走到四楼的拐角，她忽然停下。",opts:[{x:"停下，等她自己说。",aff:10,best:!0,reply:"她攥了攥画筒的带子：「……没什么。就是想说，今天谢谢你上来。」"},{x:"「明天还来吗？」",aff:6,reply:"「来。」她答得很快，答完自己愣了一下。"},{x:"「你走得真慢。」",aff:-6,reply:"她低头快走了两步，画筒在背后一下一下撞着楼梯扶手。"}]},{t:"narr",x:"她说她住的宿舍在湖边，晚上能听见水声。"},{t:"say",who:"林晚",x:"你先走吧，我要去小卖部买橡皮。"},{t:"me",x:"一起去。"},{t:"scene",photo:"lake-dorm",place:"湖边宿舍楼下",time:"周三 18:40",x:"路灯刚亮，湖面上浮着一层薄雾。"},{t:"narr",x:"小卖部只开一半的灯。她挑了一块最便宜的橡皮，又放回去。"},{t:"narr",x:"最后她买了两块，把其中一块放在你手里。"},{t:"say",who:"林晚",x:"你刚才一直站着，手会冷。"},{t:"me",x:"拿橡皮换我站着？"},{t:"say",who:"林晚",x:"算是。"},{t:"narr",x:"她把橡皮塞进笔袋，笔袋里全是断掉的炭笔，长短不一。"},{t:"choice",q:"她数那些断炭笔，数到一半停住。",opts:[{x:"「这些你都留着？」",aff:12,best:!0,reply:"她把最长的那根挑出来给你看：「断的都留着。断了也还能画。」"},{x:"「我帮你削一支。」",aff:5,reply:"她从笔袋里翻出一把小刀：「不用，削了就短了。」"},{x:"「这么短了还能画？」",aff:-8,reply:"她把笔袋拉上，没说话，一路走到宿舍楼下都没再开口。"}]},{t:"narr",x:"湖边的风带着水味。她站在路灯下面，影子拖得很长。"},{t:"say",who:"林晚",x:"我原来的学校，操场比这里小。"},{t:"me",x:"为什么转学。"},{t:"narr",x:"她想了很久，久到路灯闪了一下。"},{t:"say",who:"林晚",x:"我妈说我该换个地方。换个地方会好些。"},{t:"me",x:"（她说完看着湖，像在确认这句话对不对。）"},{t:"choice",q:"湖面上有只野鸭游过去，划开一道水纹。",opts:[{x:"「现在好些了吗。」",aff:12,best:!0,reply:"她想了很久：「……有。比刚来的时候好。」"},{x:"「换个地方挺好的。」",aff:6,reply:"「嗯。」她把画本抱紧了一点，「地方是换了。」"},{x:"「你妈说得对。」",aff:-6,reply:"她低头踢了一下台阶：「她说的不一定对。」"}]},{t:"narr",x:"她没有立刻走，把画本翻到天台那一张。"},{t:"say",who:"林晚",x:"今天这张，比昨天那张好。"},{t:"me",x:"哪里好。"},{t:"say",who:"林晚",x:"多了一个人。"},{t:"tip",x:"她的画里开始有人了，只是那些人还都背对着她。"}]},{id:"c3",title:"第三章 · 画展前夜",sub:"她把那张画挂在了最中间",photo:"campus-day",beats:[{t:"scene",photo:"crowd",place:"美术教室 · 社团展前夜",time:"周五 21:00",x:"教室里只有一盏灯亮着。"},{t:"narr",x:"社团展前一天晚上，美术教室还亮着灯。你路过，看见她站在梯子上挂画。"},{t:"me",x:"我帮你。"},{t:"say",who:"林晚",x:"……你怎么还没走。"},{t:"me",x:"看见灯亮着。"},{t:"narr",x:"她从梯子上下来，手上全是灰，指缝里也是。"},{t:"narr",x:"她挂了一整面墙：走廊、食堂、操场、宿舍楼下晾着的校服。"},{t:"narr",x:"每张画的下角都写了日期，从九月排到十一月。"},{t:"narr",x:"最中间那块位置还空着，量好了高度，钉了两颗钉子。"},{t:"say",who:"林晚",x:"那张我想挂在这里。"},{t:"narr",x:"她从画筒里抽出一张画。是天台那张，有你站在栏杆边的背影。"},{t:"narr",x:"这次不一样。画上多了一个人，坐在水塔影子边上，低头画画。"},{t:"narr",x:"是她自己。脸只有指甲盖那么大，但一眼看得出是她。"},{t:"choice",q:"你看着那张画，半天没说话。",opts:[{x:"「你终于画自己了。」",aff:14,best:!0,reply:"「嗯。」她仰头看画，「因为那天有人站在旁边，我就没那么怕了。」"},{x:"「画得真好。」",aff:8,reply:"她笑了一下，是很轻的那种：「谢谢。」"},{x:"「挂在最中间，会被很多人看。」",aff:4,reply:"「我知道。」她握紧画框，「所以我才要挂。」"}]},{t:"say",who:"林晚",x:"这张画了三个晚上。手一抖就得重来。"},{t:"narr",x:"她把画举起来对准钉子。你扶住梯子，她踩上去，梯子晃了一下。"},{t:"narr",x:"她一只手抓住你的肩膀，握得很紧，指节都白了。"},{t:"narr",x:"钉子进墙的声音很轻。画挂正了，她退后两步看。"},{t:"narr",x:"画的右下角还是空的，什么都没有写。"},{t:"narr",x:"她坐在窗台上，脚悬着，晃了两下。"},{t:"say",who:"林晚",x:"我转学过来之前，在原来的学校没有朋友。"},{t:"me",x:"为什么？"},{t:"say",who:"林晚",x:"因为我不太说话。他们觉得我怪。"},{t:"narr",x:"她低头看自己的手，手指上全是炭笔的灰。"},{t:"say",who:"林晚",x:"有人的时候我不知道说什么。没人的时候，我知道该画什么。"},{t:"choice",q:"头顶的灯管闪了一下。",opts:[{x:"「你在我面前话不少。」",aff:12,best:!0,reply:"她愣了愣：「……那不一样。」"},{x:"「不说话也没什么。」",aff:6,reply:"「你也这么觉得？」她问得很轻。"},{x:"「那你应该改一改。」",aff:-8,reply:"她把脚从窗台上收回去，说：「改不了。」"}]},{t:"say",who:"林晚",x:"但是在这里，有人会问我画的是什么。"},{t:"narr",x:"她从窗台上跳下来，落地很轻，把画筒的盖子拧紧。"},{t:"narr",x:"走廊有手电光扫过门上的玻璃，是保安在巡查。"},{t:"say",who:"林晚",x:"该走了。"},{t:"me",x:"明天几点。"},{t:"say",who:"林晚",x:"九点。我提前来一趟。"},{t:"narr",x:"锁门的声音在空走廊里响了一下，很脆。"},{t:"scene",photo:"stage",place:"展厅 · 第二天上午",time:"周六 09:10",x:"展板还带着新刷的漆味。"},{t:"narr",x:"你到的时候她已经在展厅里了，站在自己的画前面。"},{t:"narr",x:"她换了件干净的校服，头发用水梳过，耳边还湿着。"},{t:"narr",x:"最中间那张画前面站了几个人，有人凑近看那个坐着的小人。"},{t:"say",who:"美术社老师",x:"这张是谁的。"},{t:"say",who:"林晚",x:"我的。"},{t:"say",who:"美术社老师",x:"你的画里第一次有人。还是你自己。"},{t:"narr",x:"她没接话，把手背到身后，手指绞在一起。"},{t:"choice",q:"老师走了以后，她还站在原地。",opts:[{x:"「老师那句话是在夸你。」",aff:12,best:!0,reply:"「我知道。」她说，「可我还是想听别人再说一遍。」"},{x:"「画前面人挺多的。」",aff:6,reply:"她往后退了半步，让开路：「别挡着。」"},{x:"「早知道不挂出来了。」",aff:-8,reply:"她看了你一眼，很久，然后转身去搬下一张画。"}]},{t:"narr",x:"一个女生拉着同伴过来，指着画问这个人是谁。"},{t:"say",who:"林晚",x:"那是我。"},{t:"narr",x:"她说得很小声，但说出来了，说完抬了一下下巴。"},{t:"choice",q:"展厅里人越来越多，她往你这边挪了半步。",opts:[{x:"「你刚才回答得很好。」",aff:12,best:!0,reply:"她低头看鞋尖：「我说完心跳得很快。」"},{x:"「要不要去外面透口气。」",aff:5,reply:"「等一会儿。」她说，「还有人没看完。」"},{x:"「刚才被问住了吧。」",aff:-6,reply:"她抿了一下嘴：「没有。」然后一上午没再主动说话。"}]},{t:"narr",x:"十点半，她蹲下来补画右下角那行字。"},{t:"narr",x:"铅笔字很小，要蹲下才看得清：谢谢那天问我画什么的人。"},{t:"narr",x:"展厅外面开始下雨，雨点打在教学楼的玻璃上。"},{t:"scene",photo:"gate",place:"校门口 · 传达室屋檐下",time:"周六 11:40",x:"雨把台阶洗得发亮。"},{t:"narr",x:"她把画筒抱在胸前，站在屋檐下等雨小一点。"},{t:"say",who:"林晚",x:"我以前觉得，画完就够了。"},{t:"me",x:"现在呢。"},{t:"say",who:"林晚",x:"现在觉得，要有人看。"},{t:"choice",q:"雨小了一点，她把画筒往怀里紧了紧。",opts:[{x:"「我看过了。」",aff:12,best:!0,reply:"她抬头看你：「不算。」「怎么不算。」「你看的时候没说话。」"},{x:"「会有人看的。」",aff:8,reply:"「嗯。」她把画筒换个方向抱，「总得有人先看。」"},{x:"「看的人多，也不一定是好事。」",aff:-6,reply:"她把伞往自己那边偏了偏，屋檐的水滴在你肩上。"}]},{t:"narr",x:"她把一小截炭笔塞进你手心。很短，断口已经磨圆了。"},{t:"say",who:"林晚",x:"你留着，我就得一直画。"},{t:"me",x:"（炭笔在她手心里捂得很热。）"},{t:"tip",x:"画展第二天，最中间那张画前面一直站着人。"}]}],c=[{id:"c1",title:"第一章 · 点歌",sub:"她念了你的名字，念错了一个字",photo:"stage",beats:[{t:"scene",photo:"stage",place:"三号教学楼 · 五层走廊",time:"周二 午休 12:20",x:"走廊尽头那扇门虚掩着，门缝里漏出一条白光。"},{t:"narr",x:"周二午休，你替同桌去广播站送点歌条。他写了两行，字丑得没法念。"},{t:"narr",x:"楼梯爬到五层，人声就淡了。这一层只有广播站一间屋子在用。"},{t:"narr",x:"门上贴着一张手写排班表，四角用透明胶粘着，右下角已经翘起来。"},{t:"say",who:"苏念",x:"下面是今天的第三首歌。来自高一（3）班。"},{t:"narr",x:"声音从门缝里出来，也从头上的喇叭里出来，中间差了半秒。"},{t:"me",x:"（同一个人，两个声音。喇叭里那个更稳。）"},{t:"narr",x:"你抬手敲门，里面没应。歌声已经起来了，是一首很慢的老歌。"},{t:"narr",x:"你推门进去。屋里一股旧电器的味道，混着一点橘子皮的清味。"},{t:"say",who:"苏念",x:"条子放桌上。别踩地上的线。"},{t:"narr",x:"她背对着门，耳机只戴了一只，另一只挂在脖子上晃。"},{t:"narr",x:"桌上摊着一本硬皮本子，封面用马克笔写着三个字：点歌本。"},{t:"me",x:"（原来那些条子最后都进这里。）"},{t:"narr",x:"你把条子放下。她伸手抽过去，扫了一眼，眉头动了一下。"},{t:"say",who:"苏念",x:"这字，是你写的？"},{t:"choice",q:"她把条子举到台灯底下。",opts:[{x:"「我写的。你刚才念错了一个字。」",aff:12,best:!0,reply:"「哪个？」她把条子凑近，「……哦，这个字。我念错了三年。」她笑出声，「行，下次念对。」"},{x:"「同桌写的，我只负责送。」",aff:6,reply:"「哦。」她把条子夹进本子，「替我谢谢他。写得挺真诚，就是字难看。」"},{x:"「随便写的，别念也行。」",aff:-8,reply:"她把条子推回桌子中间：「那你自己拿回去。广播里不念假话。」"}]},{t:"narr",x:"她低头在本子上记了一行，笔尖有点钝，写完还描了一遍。"},{t:"say",who:"苏念",x:"你叫什么。"},{t:"me",x:"我把名字说了。她跟着念了一遍，念对了。"},{t:"say",who:"苏念",x:"记住了。以后你送条子，我排前面。"},{t:"me",x:"（这算什么，特权，还是随口一句。）"},{t:"narr",x:"她把推子慢慢推上去，红灯亮起来，屋里多了一层电流声。"},{t:"say",who:"苏念",x:"红灯亮着的时候别说话。外面都听得见。"},{t:"narr",x:"你站着没动。她对着话筒开口，肩膀是松的，跟平时不一样。"},{t:"choice",q:"一段广告的空档，她按下暂停，回头看你。",opts:[{x:"「想看你播完这一段。」",aff:14,best:!0,reply:"她愣了半秒，把边上那把椅子踢过来：「坐着。别出声。」"},{x:"「我在听歌。」",aff:6,reply:"「歌在喇叭里，不在我这儿。」她说完，还是没赶你走。"},{x:"「我马上走。」",aff:-6,reply:"「嗯。」她转回去，把音量推高了一格，像要把屋子填满。"}]},{t:"narr",x:"她念一条通知，念到一半自己停下来，把稿子上两个字划掉。"},{t:"narr",x:"红灯灭掉的那一刻，她把耳机摘下来，整个人往回缩了一截。"},{t:"say",who:"苏念",x:"播完了。你还不走？"},{t:"me",x:"（刚才那个说话的人，好像不在这间屋子里。）"},{t:"narr",x:"第二天午休，喇叭响的时候，教室里正在发上周的卷子。"},{t:"say",who:"苏念",x:"下面这首歌，来自高一（3）班。送给一个总是走最后的人——这次字念对了。"},{t:"narr",x:"整间教室静了一秒，然后有人吹口哨。你把脸埋进胳膊里。"},{t:"narr",x:"同桌在旁边笑得直拍桌子，说你这下全校都知道了。"},{t:"choice",q:"下课以后，走廊上有人学喇叭里的腔调念你的名字。",opts:[{x:"「她念得比你们好听。」",aff:16,best:!0,reply:"后面那人笑骂了一句。第二天她放歌的时候，语气比平时轻了半格。"},{x:"低头快走，装没听见。",aff:6,reply:"走廊很长。你走到头才发现，自己一路都在同手同脚。"},{x:"冲回去跟人吵了一架。",aff:-12,reply:"吵完你被叫去办公室。那天的歌照常放，只是没有报幕。"}]},{t:"scene",photo:"gate",place:"校门口 · 传达室旁边",time:"周二 17:40",x:"路灯还没亮，天是灰蓝色的。"},{t:"narr",x:"她背着一个洗得发白的帆布包，手里拎着两瓶汽水。"},{t:"say",who:"苏念",x:"喂。你害我被站长说了。"},{t:"me",x:"我说了不是我。"},{t:"say",who:"苏念",x:"现在是你了。"},{t:"narr",x:"她把其中一瓶递过来，瓶身全是水珠，凉得几乎握不住。"},{t:"choice",q:"汽水开盖的时候响了一声，很脆。",opts:[{x:"「那站长说你什么了。」",aff:10,best:!0,reply:"「说我加话。」她喝了一口，「站长说广播里不许有自己的话。我说那句是我自己的。」"},{x:"「谢了。」接过来喝。",aff:5,reply:"「不用谢。」她拧开自己那瓶，「反正超市买一送一。」"},{x:"「以后别念我名字了。」",aff:-10,reply:"她停了一下，把瓶子收回去半寸：「行。不念了。」"}]},{t:"narr",x:"两个人站在校门口，看学生一批批往外走，谁也没说话。"},{t:"say",who:"苏念",x:"你知道广播站几点开门吗。"},{t:"me",x:"十二点？"},{t:"say",who:"苏念",x:"十一点五十。我每天提前十分钟上去，把机器热一热。"},{t:"narr",x:"她说这话的时候在看马路，没有看你。"},{t:"say",who:"苏念",x:"机器凉的时候，声音会抖。"},{t:"me",x:"（她说的是机器。）"},{t:"choice",q:"绿灯亮了，她把空瓶扔进垃圾桶，回头等你。",opts:[{x:"「那明天十一点五十，我到。」",aff:12,best:!0,reply:"她扔瓶子的手停在半空：「你来干嘛。」「帮你热机器。」她停了两秒：「……随你。」"},{x:"「知道了。」",aff:4,reply:"「知道就行。」她点头，先走两步，又回头，「别迟到。」"},{x:"「你这人挺没意思的。」",aff:-8,reply:"她笑了一下，那个笑很短：「嗯，我一直这样。」然后她真的走了。"}]},{t:"narr",x:"第二天十一点五十，你站在广播站门口。门已经开着，灯也亮着。"},{t:"narr",x:"她抬头看了你一眼，把桌上另一只耳机推过来，什么也没说。"},{t:"me",x:"（耳机线绕了三圈，她大概每天都是这样收的。）"},{t:"tip",x:"点歌本上，今天多了一行你的字。"}]},{id:"c2",title:"第二章 · 停电的十分钟",sub:"没有话筒的时候，她说话很小声",photo:"lake-dorm",beats:[{t:"scene",photo:"crowd",place:"三号教学楼 · 三层走廊",time:"周四 18:38",x:"整栋楼的灯一起灭了，只有应急灯亮着。"},{t:"narr",x:"周四傍晚，整个校区跳闸。走廊里全是起哄声，有人拍栏杆。"},{t:"narr",x:"你从教室出来，被人流推着走了半层，才想起广播站的设备。"},{t:"me",x:"（那台机器刚换过，跳闸最怕烧。上去看看。）"},{t:"narr",x:"你逆着人流上楼。越往上人越少，到五层只剩你自己的鞋声。"},{t:"scene",photo:"lake-dorm",place:"广播站 · 三号教学楼顶层",time:"周四 18:45",x:"门是开的，里面一点光都没有。"},{t:"narr",x:"屋里黑得像空的。只有窗外一点路灯，照在地板上，很淡。"},{t:"say",who:"苏念",x:"……谁？"},{t:"me",x:"我。"},{t:"narr",x:"她坐在调音台后面，手机倒扣在桌上，屏幕的光一点没漏。"},{t:"say",who:"苏念",x:"别开灯。"},{t:"me",x:"为什么。"},{t:"say",who:"苏念",x:"黑的时候，我说话比较正常。"},{t:"narr",x:"你摸到椅子坐下。椅子腿刮了一下地板，她没吭声。"},{t:"narr",x:"窗外那点光勉强照出她的轮廓，还有耳机线的走向。"},{t:"say",who:"苏念",x:"你怎么上来了。"},{t:"choice",q:"她的声音比白天低，也比白天近。",opts:[{x:"「怕设备烧了。」",aff:5,reply:"「没烧。」她敲了敲调音台的边，「就是黑的。黑了也一样能播。」"},{x:"「上来看看你在不在。」",aff:12,best:!0,reply:"她安静了几秒：「……哦。」然后又补一句，「在。」"},{x:"「上来躲一下，下面太吵。」",aff:4,reply:"「这层是全校最安静的地方。」她说，「所以我才天天上来。」"}]},{t:"narr",x:"楼下有人在喊班主任。声音穿过两层楼板，变得很闷。"},{t:"say",who:"苏念",x:"你知道我为什么做广播吗。"},{t:"me",x:"因为你声音好听。"},{t:"say",who:"苏念",x:"因为我说话的时候，看不见对面的人。"},{t:"narr",x:"她说完这句，屋里静了很久。静到你能听见她的呼吸。"},{t:"me",x:"（她每天中午对着话筒说二十分钟，原来是在躲人。）"},{t:"choice",q:"她停顿了很久，手指在桌面上敲了两下。",opts:[{x:"「那你现在看得见我吗。」",aff:12,best:!0,reply:"「看得见。」她说，「黑的时候反而看得见。因为不用管表情。」"},{x:"「那你现在跟我说话，紧张吗。」",aff:8,reply:"「紧张。」她回答得很快，然后又补一句，「但是还行。」"},{x:"「你话挺多的啊。」",aff:-8,reply:"「……嗯。」她就不说了。楼下又开始起哄，她一直没再开口。"}]},{t:"narr",x:"她伸手在桌面上摸，摸到那本硬皮本子，翻了两页。"},{t:"say",who:"苏念",x:"有件事我一直没跟人说。"},{t:"me",x:"什么事。"},{t:"say",who:"苏念",x:"点歌本里有一页，我三年都没放过。"},{t:"narr",x:"她把本子推过来，指尖压在其中一页上，正好落在光里。"},{t:"narr",x:"那一页有三行字，同一天，同一首歌，笔迹一模一样。"},{t:"me",x:"（三年，同一天。每年都有人记得这一天。）"},{t:"say",who:"苏念",x:"第一年我以为是恶作剧。第二年我觉得有点吓人。"},{t:"say",who:"苏念",x:"第三年，我把它留着了。"},{t:"choice",q:"她的手指还压在那三行字上，没有拿开。",opts:[{x:"「为什么留着。」",aff:10,best:!0,reply:"「因为放一次就少一次。」她说，「我总觉得，放完那天，就没人再点了。」"},{x:"「那今年放吗。」",aff:6,reply:"「不知道。」她把本子合上，「今年再看吧。」"},{x:"「会不会是有人在整你。」",aff:-6,reply:"「整了三年？」她笑了一声，很短，「那也太有耐心了。」"}]},{t:"narr",x:"楼下忽然一片欢呼。电来了，走廊的灯管一起嗡嗡响。"},{t:"narr",x:"顶灯闪了两下，整间屋子亮得刺眼，你看清了桌上的灰。"},{t:"narr",x:"她立刻坐直，把手机翻过来，恢复成平时那个样子。"},{t:"say",who:"苏念",x:"行了，你回去吧。晚自习要开始了。"},{t:"me",x:"（刚才那个人，被灯管一闪就收起来了。）"},{t:"narr",x:"你走到门口，手已经搭在门把上。"},{t:"choice",q:"她在后面叫住你。",opts:[{x:"停下来，等她说完。",aff:14,best:!0,reply:"「……明天午休，你来一趟。」她低头调音，「我想放一首歌。没人点的那种。」"},{x:"「有事明天说。」继续走。",aff:5,reply:"她哦了一声。第二天午休，喇叭里放了一首很安静的曲子，没有报幕。"},{x:"回头看她。",aff:8,reply:"她张了张嘴，最后只说：「……没事。走吧。」"}]},{t:"narr",x:"第二天十二点二十，喇叭响了一声，没有人报幕。"},{t:"narr",x:"是一首钢琴曲，很短，放完只用了两分半。"},{t:"say",who:"苏念",x:"这首不送人。放给我自己听。"},{t:"narr",x:"走廊上有人问这是谁点的，没人答得上来。"},{t:"me",x:"（那把椅子还在原位。昨天的事，好像没被收走。）"},{t:"narr",x:"放学的时候，你在广播站门口捡到一张纸条，压在门缝里。"},{t:"narr",x:"纸上只有一句：明天中午，还是十一点五十。"},{t:"choice",q:"纸条背面还留着半行字，被撕掉了。",opts:[{x:"把纸条夹进书里，收好。",aff:12,best:!0,reply:"第二天你把纸条塞回门缝。她看见了，什么也没问，只把椅子往旁边踢了踢。"},{x:"扔了，反正记住了。",aff:4,reply:"你没带。第二天她照常开门，只是那把椅子被她摆回了墙边。"},{x:"拿去问同桌是谁写的。",aff:-12,reply:"传言走得比广播快。第二天全年级都在猜广播站长给谁递了纸条。"}]},{t:"tip",x:"点歌本上那三行字，第四行还空着。"}]},{id:"c3",title:"第三章 · 最后一期",sub:"毕业前，她把话筒递给了你",photo:"track-star",beats:[{t:"scene",photo:"stage",place:"广播站 · 三号教学楼顶层",time:"周五 17:00",x:"夕阳从百叶窗的缝里切进来，落在调音台上。"},{t:"narr",x:"学期最后一次播音。她提前一个小时就到了，桌上摊着写了三页的稿子。"},{t:"say",who:"苏念",x:"你来干嘛。"},{t:"me",x:"听最后一期。"},{t:"say",who:"苏念",x:"还没开始。"},{t:"narr",x:"她没抬头，手指在稿子边缘来回折，折出一道白印。"},{t:"narr",x:"第一页第一行写着：「这里是西子之声，我是苏念。这可能是我最后一期。」"},{t:"me",x:"最后一期？"},{t:"say",who:"苏念",x:"下学期高三，站长要换人。"},{t:"narr",x:"她说这话的语气跟平时一模一样，像在念一条通知。"},{t:"me",x:"（她连告别都要照着稿子念。）"},{t:"choice",q:"她把稿子拿回去，抚平边角。",opts:[{x:"「那这期我陪你播。」",aff:14,best:!0,reply:"「你？」她挑眉，「你普通话过关吗。」「不过关。」你说，「但我想试试。」"},{x:"「以后还能听到你说话吗。」",aff:6,reply:"「能啊。」她顿了一下，「就是不在喇叭里了。」"},{x:"「挺好，终于不用听你念错字了。」",aff:-8,reply:"她笑了一下，把稿子叠起来：「是啊，挺好。」"}]},{t:"narr",x:"她把稿子分成两叠，一叠推到你面前，一叠留在自己手边。"},{t:"say",who:"苏念",x:"你的那份，我只写了大纲。剩下的你自己说。"},{t:"me",x:"我不会。"},{t:"say",who:"苏念",x:"按稿子念才不像人。"},{t:"choice",q:"她把你那叠稿子上的第一句圈了出来。",opts:[{x:"「这句我自己写。」",aff:12,best:!0,reply:"她把笔递过来：「写。写完给我看。」你写了三行，她划掉一行，在剩下两行旁边打了个勾。"},{x:"「照着你的写就行。」",aff:5,reply:"「照着我的，就永远是我的声音。」她说完，还是把那句留在了原处。"},{x:"「这句能删掉吗。」",aff:-6,reply:"「删。」她把笔帽盖上，「反正也没人听。」她说得很轻，你听见了。"}]},{t:"narr",x:"十七点整，喇叭先响了一声电流。她把手压在推子上等了两秒。"},{t:"narr",x:"十七点二十，她把另一个话筒推到你面前，自己往旁边挪了半个位置。"},{t:"say",who:"苏念",x:"我念一句，你念一句。别抢。"},{t:"say",who:"苏念",x:"「这里是西子之声。」"},{t:"me",x:"这里是西子之声。"},{t:"say",who:"苏念",x:"「我是苏念。」"},{t:"me",x:"我是……"},{t:"narr",x:"她忽然伸手，把你的话筒按低了一点。"},{t:"say",who:"苏念",x:"这句我自己念。"},{t:"narr",x:"整期节目，她念得比任何一次都慢。"},{t:"narr",x:"中间有两处她停下来喝水。杯子早就空了，她还是在喝。"},{t:"narr",x:"你念错了一个词，把同学念成同雪。她在旁边低了低头，忍住没笑。"},{t:"say",who:"苏念",x:"没事。接着念。"},{t:"narr",x:"第二页念完，她翻到第三页，手停住了。那页只有一行字。"},{t:"me",x:"（那不是稿子。）"},{t:"narr",x:"她盯着那一行看了很久，然后把第三页翻过去，扣在桌上。"},{t:"say",who:"苏念",x:"最后一段，我不念了。"},{t:"choice",q:"红灯还亮着，外面整座学校都在听。",opts:[{x:"「那我帮你把话筒扶正。」",aff:16,best:!0,reply:"她看了你一眼，把话筒拉近：「这里是西子之声。我是苏念。」她停了一下，声音比稿子上慢得多。"},{x:"「要不要先停一下。」",aff:8,reply:"「不用。」她吸了一口气，「停了，就再也开不了了。」"},{x:"「那我把稿子念完。」",aff:-10,reply:"「不要。」她按住你的稿子，「这期是我的最后一期。念稿的最后一期，我不要。」"}]},{t:"narr",x:"她没有念稿。她说：这里是西子之声，我是苏念。"},{t:"narr",x:"我要谢谢一个人。他每次都走最后，所以我每次都能看见他。"},{t:"narr",x:"喇叭里安静了两秒。你听见她把纸放下的声音。"},{t:"narr",x:"她把推子一个一个推到底，红灯灭了。"},{t:"say",who:"苏念",x:"好了。"},{t:"narr",x:"播完，她关掉设备，坐着没动。窗外的天已经全暗了。"},{t:"choice",q:"调音台上还亮着一盏小灯。",opts:[{x:"「下次我走前面，你跟上。」",aff:14,best:!0,reply:"她转过头，眼睛有点红：「行啊。」然后她伸手，把耳机分了一只给你，「先听首歌。没人点的。」"},{x:"「我会记得你的声音。」",aff:8,reply:"「声音有什么好记的。」她笑，「记点别的。」"},{x:"什么也不说，帮她把稿子收好。",aff:6,reply:"她把稿子接过去，抱在怀里，很久才说：「谢谢你来。」"}]},{t:"narr",x:"她从抽屉里拿出那本点歌本，翻到最后一页。"},{t:"narr",x:"最后一条是今年写的。跟前面三年同一天，同一首歌。"},{t:"say",who:"苏念",x:"今年我放了。放在最后。"},{t:"narr",x:"前奏起来的时候，她跟着哼了两句，跑调。你也跟着哼，谁也没停。"},{t:"scene",photo:"track-star",place:"操场 · 跑道外侧",time:"周五 19:10",x:"操场只剩两盏灯，跑道是暗红色的。"},{t:"narr",x:"锁门的时候，她把钥匙在手里抛了一下，又接住。"},{t:"say",who:"苏念",x:"明天开始，钥匙交给下一届。"},{t:"me",x:"你舍得吗。"},{t:"say",who:"苏念",x:"不舍得。"},{t:"say",who:"苏念",x:"但站长的位置，不能让给舍不得的人。"},{t:"narr",x:"她说完自己愣了一下，像被自己这句话吓到。"},{t:"choice",q:"跑道边的灯把两个人的影子拉得很长。",opts:[{x:"「你走后面半步，我走前面。」",aff:12,best:!0,reply:"她跟上来了，脚步声就在你后面半步：「半步够了。多了听不见，少了看不清。」"},{x:"「你先走，我看着你。」",aff:6,reply:"她走了十几步，忽然停下来回头：「你还站着？」「看你走。」她说：「无聊。」但还是等你跟上。"},{x:"「就这样吧，散了。」",aff:-6,reply:"「行。」她把包带往肩上一提，走得很快。你落后了半条跑道。"}]},{t:"narr",x:"走到操场门口，她停下来，把一只耳机塞进你耳朵。"},{t:"narr",x:"里面还在放那首歌。她按了暂停，又按了一次播放。"},{t:"say",who:"苏念",x:"现在，你走前面。"},{t:"narr",x:"你走在前面。身后是她的脚步声，一直没落下。"},{t:"tip",x:"广播站的门上换了新的排班表，第一行是空的。"}]}],i=[{id:"c1",title:"第一章 · 402 的灯",sub:"那间教室每晚亮到十点半",photo:"campus-aerial",beats:[{t:"scene",photo:"campus-aerial",place:"实验楼 402 · 竞赛教室",time:"周三 19:00",x:"黑板上留着上一节课的受力分析，粉笔灰没擦干净。"},{t:"narr",x:"物理老师把一摞卷子塞给你，说送到实验楼四楼，放讲台就行。"},{t:"narr",x:"楼道声控灯一层一层亮，又一层一层灭。你数到第四层。"},{t:"narr",x:"402 的门虚掩着，整层楼只有这一间亮着。"},{t:"narr",x:"灯管有一根在闪，隔两秒暗一下，像在倒数。"},{t:"narr",x:"你推门进去，整间教室只有一个人，坐在第一排。"},{t:"narr",x:"她面前摊着三本练习册，笔尖动得很快，纸边压着一块橡皮。"},{t:"say",who:"顾青",x:"卷子放讲台。别碰桌上的东西。"},{t:"narr",x:"你把卷子放在讲台边。她头都没抬，笔也没停。"},{t:"narr",x:"讲台边一排烧杯，插着几支笔，杯身上贴着日期。"},{t:"narr",x:"黑板上有一道题，写到一半停住了。你多看了两眼。"},{t:"say",who:"顾青",x:"看得懂？"},{t:"narr",x:"她还是没抬头。笔尖停在纸上，压出一个小点。"},{t:"choice",q:"她把笔放下，等你回答。",opts:[{x:"「看不懂。但这里好像少了一个条件。」",aff:12,best:!0,reply:"她看了你三秒，低头重新看题：「……对。少了一个。」她划掉半页，「你是第一个看出来的。」"},{x:"「看不懂。」",aff:5,reply:"「那就别看了。」她继续写，笔尖划得比刚才快。"},{x:"「这种题有什么好做的。」",aff:-8,reply:"她把笔帽扣上，声音没什么起伏：「门在那边。」"}]},{t:"narr",x:"她划掉半页，重新起了一行，写得比刚才慢。"},{t:"say",who:"顾青",x:"卷子按班分。一班放左边，二班放右边。"},{t:"narr",x:"你分了二十分钟。她一直在写，中间只喝了一口水。"},{t:"narr",x:"分完卷子，讲台角上多出两张，没人认领。"},{t:"say",who:"顾青",x:"多了两张。"},{t:"me",x:"（她连这个都数过。）"},{t:"say",who:"顾青",x:"去教务处补印。或者留着，明天有人缺。"},{t:"narr",x:"你把那两张夹进自己的文件夹。她看见了，没说别的。"},{t:"narr",x:"她把那道题重写了一遍，写完，把粉笔递给你。"},{t:"say",who:"顾青",x:"你来。"},{t:"me",x:"我不会。"},{t:"say",who:"顾青",x:"不会才要写。站着看，永远学不会。"},{t:"narr",x:"你握着粉笔站在黑板前。她在旁边看着，一句话也不说。"},{t:"narr",x:"你写错了三步。她终于伸手，把其中一行圈了出来。"},{t:"say",who:"顾青",x:"这里。符号反了。"},{t:"narr",x:"她的手指还停在黑板上，指甲剪得很短，指腹有粉笔灰。"},{t:"choice",q:"她没有把手收回去。",opts:[{x:"「那你为什么不早说。」",aff:12,best:!0,reply:"「因为你自己发现的时候，才记得住。」她收回手，「我讲一遍，你下次还会错。」"},{x:"「谢谢。」",aff:6,reply:"「不用谢。」她回到座位，「题是你自己写的。」"},{x:"把粉笔放下。",aff:-8,reply:"「随你。」她翻开练习册，没再理你。"}]},{t:"narr",x:"你把那一行擦掉，重写。这次她没说话，退回了座位。"},{t:"narr",x:"写完最后一步，你回头看她。她低着头在翻书。"},{t:"say",who:"顾青",x:"答案对。过程缺一行。"},{t:"me",x:"哪一行。"},{t:"say",who:"顾青",x:"自己找。找不到就再写一遍。"},{t:"narr",x:"你找了七分钟。她等了七分钟，一次都没催。"},{t:"narr",x:"十点，楼下保安拿手电往上照，喊了一声锁楼门。"},{t:"say",who:"顾青",x:"还有半小时。"},{t:"choice",q:"她把练习册合上，笔尖朝上插进笔筒。",opts:[{x:"「你每天都在这儿？」",aff:10,best:!0,reply:"「嗯。」她把钥匙放在桌角，「你来了坐第三排，第一排粉笔灰大。」"},{x:"「你不累吗。」",aff:5,reply:"「累。」她说，「但题不会因为我累就变简单。」"},{x:"「我先走了。」",aff:-6,reply:"「嗯。」她低头收拾东西，没有再说别的。"}]},{t:"narr",x:"十点半，整层楼只剩这一间亮着。灯管闪了一下，没亮回来。"},{t:"narr",x:"她踩上椅子，把灯管拧了半圈，教室重新白起来。"},{t:"say",who:"顾青",x:"这根快坏了。明天得换。"},{t:"narr",x:"你扶着椅背。她的重量落在椅面上，很轻。"},{t:"say",who:"顾青",x:"钥匙在门卫那儿。教室六点开，我六点零五到。"},{t:"narr",x:"她跳下来，把手在裤子上擦了两下，灰落在地板上。"},{t:"choice",q:"她的手心还是灰的。",opts:[{x:"「明天我带一根新的来。」",aff:12,best:!0,reply:"「规格是三十二瓦。」她把手在裤子上又擦了一下，「带错了装不上。」"},{x:"「要不要我去报修。」",aff:6,reply:"「报修单在一楼。你填，我签字。」她把椅子推回原位。"},{x:"「这种事让后勤做。」",aff:-8,reply:"「后勤下班了。」她拿起书包，「灯是我在用，我自己换。」"}]},{t:"scene",photo:"campus-day",place:"实验楼 楼下",time:"22:35",x:"路灯只亮了一半，梧桐的影子铺在地上。"},{t:"narr",x:"她关灯，锁门，钥匙在锁孔里转了两圈才拔出来。"},{t:"narr",x:"下楼时她走在前面，两级台阶一步，脚步声很轻。"},{t:"narr",x:"到了楼门口，她停下，把书包带往肩上提了提。"},{t:"say",who:"顾青",x:"你下次还来吗。"},{t:"choice",q:"她站在门口，手还搭在开关上。",opts:[{x:"「来。明天六点零五。」",aff:14,best:!0,reply:"「六点零五。」她重复了一遍，像在核对答案，「迟到不等。」"},{x:"「看情况。」",aff:5,reply:"「看情况就是不来。」她按下开关，教室黑了。"},{x:"「不来了。这题太难。」",aff:-10,reply:"她停了两秒，说：「难才要学。」然后她先走了。"}]},{t:"narr",x:"她点了下头，转身往宿舍的方向走，没有回头。"},{t:"narr",x:"你站在原地，直到她拐进宿舍楼的门洞。"},{t:"me",x:"（明天，六点零五。）"},{t:"tip",x:"黑板右下角多了一行小字：明天，同一时间。"}]},{id:"c2",title:"第二章 · 错题本",sub:"她那本错题本，第一页不是题",photo:"campus-day",beats:[{t:"scene",photo:"campus-day",place:"自习室 · 周六",time:"14:00",x:"整间自习室只有翻页声，吊扇转得很慢。"},{t:"narr",x:"周六下午，你抱着自己的错题本去自习室。她已经在了。"},{t:"narr",x:"她占了两张桌子，一张放本子，一张放卷子和笔袋。"},{t:"narr",x:"桌上摊着她的错题本，厚得像一块砖，书脊用胶带缠过。"},{t:"me",x:"这么多？"},{t:"say",who:"顾青",x:"从高一到现在。一千两百道。"},{t:"me",x:"你也会错这么多？"},{t:"say",who:"顾青",x:"我不是天才。我只是把错过的都记住了。"},{t:"narr",x:"她把本子翻到第一页，推到你面前。"},{t:"narr",x:"第一页不是题。是一行字，写得很用力。"},{t:"narr",x:"「如果这次还是第二，就再也不要相信努力有用。」"},{t:"narr",x:"字迹很重，笔尖把纸戳出了一个小洞，洞边起了毛。"},{t:"choice",q:"她看着窗外，没有说话。",opts:[{x:"「那后来呢？还是第二吗。」",aff:12,best:!0,reply:"「是。」她说，「连续三次。」她转回来，「然后我第四次拿了第一。所以这句话我没划掉，留着当证据。」"},{x:"「这句话挺吓人的。」",aff:6,reply:"「吓人吗。」她笑了一下，「那时候我是认真的。」"},{x:"把本子合上还给她。",aff:-6,reply:"「不看也行。」她把本子收回去，塞进包里，拉链拉得很响。"}]},{t:"narr",x:"她把本子拿回去，指腹在那行字上按了一下。"},{t:"say",who:"顾青",x:"写这行字那天，我在楼道里坐到十二点。"},{t:"say",who:"顾青",x:"第二天照样六点起。"},{t:"narr",x:"你翻开自己的错题本。薄薄十几页，字迹潦草，还有几页空着。"},{t:"say",who:"顾青",x:"拿来。"},{t:"narr",x:"她把你的本子拿过去，一页一页翻，翻得很慢。"},{t:"say",who:"顾青",x:"你这不叫错题本。这叫草稿纸。"},{t:"choice",q:"她从笔袋里抽出一支红笔。",opts:[{x:"「那你教我。」",aff:12,best:!0,reply:"她停了一下：「教你可以。但我很严格。」「行。」你说。她低下头继续写，嘴角有一点没藏住的笑。"},{x:"看着她写。",aff:6,reply:"她写了半页，抬头：「看什么。」「看你写字。」「……无聊。」她耳朵有点红。"},{x:"「别写了，我自己来。」",aff:-8,reply:"「好。」她把本子推回来，红笔盖好，放回笔袋。"}]},{t:"narr",x:"她写字的时候手腕悬着，笔尖不碰纸边，一行一行很齐。"},{t:"narr",x:"第一页她写了六行，全是问句，一个答案都没有。"},{t:"me",x:"（她连批注都用问的。）"},{t:"say",who:"顾青",x:"这一页，你重做一遍。做完给我看。"},{t:"narr",x:"你做了四十分钟。她做完了三套卷子，一声不响。"},{t:"narr",x:"你卡在第三题，笔尖在纸上停了很久，墨积成一个小点。"},{t:"say",who:"顾青",x:"卡住了。"},{t:"narr",x:"她没抬头，但把椅子往你这边挪了半米。"},{t:"choice",q:"她的椅子停在离你半米的地方。",opts:[{x:"「第三步我不知道该不该用能量守恒。」",aff:12,best:!0,reply:"「可以用。」她说，「但你先说清楚，哪一段能量守恒。」她把你的纸转过去，手指点在第一步，「这里就错了。」"},{x:"「你再等我五分钟。」",aff:5,reply:"「等。」她翻回自己的卷子，「五分钟后我来收。」"},{x:"把本子合上，说不做了。",aff:-8,reply:"她把红笔盖上：「不做完，今天就别走。」"}]},{t:"narr",x:"她把椅子挪过来，坐在你旁边，肩膀离你一个拳头。"},{t:"narr",x:"她讲题的时候不看你，只看纸，笔尖在题目上一下一下地点。"},{t:"narr",x:"讲完，她抬头，等了两秒，才开口。"},{t:"say",who:"顾青",x:"懂了吗。"},{t:"choice",q:"她的笔还停在第三步。",opts:[{x:"「第三步懂了。第四步你再讲一遍。」",aff:10,best:!0,reply:"「第四步和第三步是一回事。」她嘴上这么说，还是又讲了一遍，讲得比刚才慢。"},{x:"「懂了。」",aff:5,reply:"「那就写。」她把笔递给你，「写出来才算懂。」"},{x:"「差不多吧。」",aff:-6,reply:"「差不多就是不懂。」她把卷子抽回去，「重讲。」"}]},{t:"narr",x:"五点，管理员来锁门。她把两本本子叠在一起，抱在怀里。"},{t:"narr",x:"你翻开自己的本子。十一页批注，红笔，一行一行。"},{t:"narr",x:"最后一页的角落，她写了一行很小的话。"},{t:"narr",x:"「第三题你其实会，只是不敢写。」"},{t:"narr",x:"你抬头看她。她已经在收拾笔袋，动作很慢。"},{t:"scene",photo:"crowd",place:"食堂 二楼",time:"17:40",x:"窗口只剩两个还开着，汤桶往上冒白汽。"},{t:"narr",x:"她端着餐盘在角落坐下，盘里只有两个素菜和一份米饭。"},{t:"narr",x:"你把自己盘里的鸡腿夹到她碗边。"},{t:"say",who:"顾青",x:"不用。"},{t:"me",x:"我不爱吃。"},{t:"narr",x:"她看了你两秒，没再推，把鸡腿吃了，骨头剔得很干净。"},{t:"say",who:"顾青",x:"你错题本上的第三题，其实你会。"},{t:"me",x:"我不会。"},{t:"say",who:"顾青",x:"你会。你只是不敢写。写错了要重写，所以干脆不写。"},{t:"narr",x:"你没说话。她也没再往下说，低头喝汤。"},{t:"scene",photo:"campus-aerial",place:"实验楼 后面",time:"18:20",x:"墙根下立着一块小黑板，粉笔装在铁盒里。"},{t:"narr",x:"吃完饭，她带你绕到实验楼后面。小黑板上写着四个字：今日错题。"},{t:"say",who:"顾青",x:"从今天起，你每天写一道。写在这儿，我每天来看。"},{t:"choice",q:"她把一截粉笔放进你手里。",opts:[{x:"「写错了你会不会笑我。」",aff:14,best:!0,reply:"「我笑你干什么。」她把铁盒盖上，「我自己写了一千两百道。第一道错了七遍。」"},{x:"「写什么？」",aff:6,reply:"「随便。写你最不想写的那道。」她指了指黑板右下角，「从那儿开始。」"},{x:"「这有什么用。」",aff:-8,reply:"她把粉笔从你手里拿回去，放回铁盒：「没用。你别写了。」"}]},{t:"narr",x:"你在黑板右下角写下第一道题，字歪得厉害。"},{t:"narr",x:"她站在旁边看，看完，把这道题抄进了自己的本子。"},{t:"me",x:"（她抄我的错题。）"},{t:"tip",x:"她合上本子，说：明天六点零五，别迟到。"}]},{id:"c3",title:"第三章 · 保送名单",sub:"名单上有她，没有你",photo:"track-aerial",beats:[{t:"scene",photo:"crowd",place:"公告栏前",time:"周一 12:00",x:"名单贴出来的时候，人群围了三层。"},{t:"narr",x:"周一中午，竞赛保送名单贴出来了，纸还是新的，边角被风吹得翻卷。"},{t:"narr",x:"第一行是顾青。省一，集训队，保送。"},{t:"narr",x:"你从头看到尾，没有自己的名字。"},{t:"narr",x:"你又看了一遍。这一遍看得比刚才慢。"},{t:"narr",x:"她站在人群外面，手里捏着两张纸，没挤进去看。"},{t:"say",who:"顾青",x:"看了。"},{t:"me",x:"看了。恭喜。"},{t:"say",who:"顾青",x:"……嗯。"},{t:"narr",x:"她把其中一张纸递给你。是集训队的报名表。"},{t:"narr",x:"表格右下角「推荐人」那一栏空着，横线画得很直。"},{t:"me",x:"这是什么。"},{t:"say",who:"顾青",x:"我推荐你。"},{t:"me",x:"我不在名单上。"},{t:"say",who:"顾青",x:"名单是去年的成绩。推荐名额是我的。"},{t:"choice",q:"她把笔也递过来。",opts:[{x:"「你为什么要给我。」",aff:12,best:!0,reply:"「因为你第三题会做。」她说，「会做的人不该站在名单外面。」"},{x:"「你自己留着吧。」",aff:5,reply:"「我用不上。」她把表塞回你手里，「我已经保送了。」"},{x:"「这算可怜我吗。」",aff:-10,reply:"她看了你很久：「我从来没可怜过你。」"}]},{t:"narr",x:"你把表格对折，又展开，纸角被捏出了印子。"},{t:"say",who:"顾青",x:"这儿太吵。跟我来。"},{t:"narr",x:"她转身往操场走，也没等你回答，脚步没有放慢。"},{t:"scene",photo:"track-aerial",place:"操场 看台",time:"周一 17:30",x:"跑道上有体育生在跑最后一圈，哨子声一阵一阵。"},{t:"narr",x:"看台最上面一排晒了一天，台阶还是温的。"},{t:"say",who:"顾青",x:"填。今天下午截止。"},{t:"narr",x:"你借了她的笔。笔身是凉的，握了半天才热。"},{t:"narr",x:"姓名那一栏你写了三遍，前两遍都划掉了。"},{t:"say",who:"顾青",x:"划掉的地方不要留。重写一张。"},{t:"narr",x:"她从书包里又拿出一张空表，铺在台阶上，用手压住。"},{t:"choice",q:"她把表推到你面前，纸比刚才那张新。",opts:[{x:"「你早就多拿了一张。」",aff:12,best:!0,reply:"「拿了三张。」她说，「你写字会抖，我知道。」"},{x:"「谢谢。」",aff:6,reply:"「不用谢。」她把笔帽咬在嘴里，「写完给我看。」"},{x:"「你是不是觉得我肯定填不好。」",aff:-8,reply:"「我觉得你会填好。」她把笔放下，「但你现在这个样子，填不好。」"}]},{t:"narr",x:"你重新填。这次一笔一划，写到最后手不抖了。"},{t:"narr",x:"填完，她拿过去看了一遍，用红笔改了两个地方。"},{t:"say",who:"顾青",x:"可以了。"},{t:"choice",q:"红笔迹还没干。",opts:[{x:"「你改了什么。」",aff:10,best:!0,reply:"「专业方向。你填的是理论，你适合实验。」她指着那一栏，「你手稳。」"},{x:"「哪里错了。」",aff:5,reply:"「不算错。」她说，「写得不清楚，会被退回来。」"},{x:"「你别改了。」",aff:-6,reply:"她把红笔盖上，把表推回给你：「那你自己交。」"}]},{t:"narr",x:"她把表装进一个透明文件袋，拉好封口，递给你。"},{t:"narr",x:"跑道上的人散了。远处的哨子响了两声，停了。"},{t:"narr",x:"她看着公告栏的方向，看了很久，没有说话。"},{t:"say",who:"顾青",x:"我下个月就走。"},{t:"me",x:"去哪儿。"},{t:"say",who:"顾青",x:"集训队。在北边。"},{t:"narr",x:"她说这话的时候没有转身，手撑着后面的台阶。"},{t:"choice",q:"她说完，第一次没有立刻走。",opts:[{x:"「那我在名单上见。」",aff:14,best:!0,reply:"她愣了一下，然后笑了。是那种真的笑，眼睛弯起来：「行。名单上见。」"},{x:"「一路顺风。」",aff:7,reply:"「嗯。」她点头，走了两步，又回头，「你也是。」"},{x:"「那我以后找谁讲题。」",aff:-8,reply:"「找你自己。」她把手插进校服口袋，「我讲过的，你都记着。」"}]},{t:"narr",x:"她站起来往教学楼走。走了十几步，又回头看了一眼。"},{t:"scene",photo:"campus-aerial",place:"实验楼 402 · 竞赛教室",time:"周四 21:00",x:"灯管换过了，白得有点刺眼。"},{t:"narr",x:"周四晚上，402 的灯还亮着。她还在。"},{t:"narr",x:"桌上摆着两摞卷子，一摞是她的，一摞是你的。"},{t:"say",who:"顾青",x:"坐。今天讲最后三题。"},{t:"narr",x:"她讲得比平时快。讲完一道，就把那道题从卷子上撕下来给你。"},{t:"narr",x:"十点半，最后一题讲完。她把粉笔放回铁盒，盖子扣了两次。"},{t:"say",who:"顾青",x:"这本给你。"},{t:"narr",x:"她从书包里拿出一本错题本，厚得像一块砖，书脊用胶带缠过。"},{t:"me",x:"你的那本？"},{t:"say",who:"顾青",x:"一千两百道。你看得完。"},{t:"choice",q:"她把本子放在桌角，推过来。",opts:[{x:"「我会一道一道做完。」",aff:12,best:!0,reply:"「做完不用给我看。」她说，「做完了，你自己就知道了。」"},{x:"「太多了，我看不完。」",aff:5,reply:"「一天五道。四个月。」她算得很快，「够。」"},{x:"「你带走吧，我用不上。」",aff:-10,reply:"她把本子拿回去，放进书包，一句话都没有说。"}]},{t:"narr",x:"你翻开第一页。那行字被划掉了，划线很用力。"},{t:"narr",x:"下面重新写了一句：「努力有没有用，要看跟谁一起努力。」"},{t:"narr",x:"你抬头，她已经在关窗，一扇一扇地关，插销都插好。"},{t:"say",who:"顾青",x:"灯我关了。钥匙还给门卫，他知道你。"},{t:"narr",x:"她走到门口，停住，手搭在门框上，没有回头。"},{t:"say",who:"顾青",x:"名单上见。"},{t:"tip",x:"黑板右下角留着三个字：第三题。"}]}],s=[{id:"m1",noPhoto:!0,title:"第一幕 · 十月，问清楚",sub:"我提前到了，站在树下等你",tone:"blue",beats:[{t:"scene",place:"约好的地方 · 树下",time:"十月 · 下午四点多",x:"天还亮着，风有点凉。"},{t:"narr",x:"十月，高二。我们不在一个学校，也都不是住宿生。"},{t:"narr",x:"平时经常不上晚自习，四点多就放学。我家离得不远，通常先回家把书包放下，玩一会儿，吃过饭再出来。"},{t:"narr",x:"你今天不知道我为什么叫你出来。"},{t:"me",x:"（可我一路都在想这件事。越想越堵，越想越气。）"},{t:"narr",x:"我172，站在你185旁边也不算矮。"},{t:"narr",x:"我的头发不算特别长，有点碎发和刘海，眼睛大，别人一般都会说我好看。"},{t:"narr",x:"你留着微分碎盖，头发有一点点遮眼睛。人有时候很抽象，有时候又冷淡平淡。"},{t:"narr",x:"我们在一起四个月了。亲亲抱抱都是日常，感情一直很好。"},{t:"narr",x:"可你有一个前女友。十四岁谈到十六岁，后来被老师和家长一起拆散。"},{t:"narr",x:"你低沉抑郁了很长一段时间，变得很冷漠。"},{t:"narr",x:"你们分手五个多月了。你看起来已经正常了一些，可偶尔还是会和她聊天。"},{t:"me",x:"（我暗恋你大半年。甚至在你刚分手的时候，偷偷开心过。）"},{t:"me",x:"（后来又觉得自己这样很坏。）"},{t:"narr",x:"现在我和你在一起了。我很爱你，可我也很在意她。"},{t:"narr",x:"我不甘心，也不得不承认，她可能确实好看、优秀。"},{t:"me",x:"（但我今天一定要问清楚，也一定要让你把她删了。）"},{t:"narr",x:"我提前到了，站在树下等你。"},{t:"narr",x:"四点多天还亮着，风有点凉。"},{t:"choice",q:"这段等待里，你在想什么。",opts:[{x:"把想说的话在心里过一遍，一句都不许软。",best:!0,reply:"你把每一句都过了一遍。过到最后，发现自己只记得第一句。"},{x:"算了，见到人再说。",reply:"你决定不想了。可脚在原地挪了三次。"},{x:"想他会不会不来。",reply:"你把这个念头按下去。按了两次，它又浮上来。"}]},{t:"narr",x:"远远看见你走过来。"},{t:"narr",x:"微分碎盖的头发遮着一点眼睛，还是那副淡淡的样子。"},{t:"me",x:"（我明明想了一路狠话。一看见你，心先软了一半。）"},{t:"me",x:"（可一想到你手机里可能还留着那个人，我心里又堵得慌。）"},{t:"narr",x:"你走过来，牵住我。"},{t:"narr",x:"坐下以后，你问我。"},{t:"say",who:"云狐",x:"怎么了……宝宝……你说。"},{t:"narr",x:"我没立刻说话。先低头抠了抠你的手指尖，想把语气装得随便一点。"},{t:"narr",x:"可手心全是汗。"},{t:"choice",q:"第一句，怎么开口。",opts:[{x:"「你最近……还跟她聊天吗？别骗我。」",best:!0,reply:"你说完，听见自己声音在抖。"},{x:"「我有个事想问你，你别急。」",reply:"你给他打了个预防针。他反而更紧张了。"},{x:"先不说话，把头靠在他肩上。",reply:"你靠了两秒，又坐直了。有些话靠着说不出口。"}]},{t:"narr",x:"你愣了一下。"},{t:"say",who:"云狐",x:"你说谁呀？那个坏女孩吗？我早不给她发消息。"},{t:"me",x:"少来，你知道我说的是谁。"},{t:"narr",x:"我把手往回抽了一下，又没舍得，重新抓住你。"},{t:"me",x:"你不给她发……那她找你呢？你回没回？聊天记录是不是还在？"},{t:"say",who:"云狐",x:"她会给我发的，我不会回。"},{t:"me",x:"不回和删掉，是两回事。"},{t:"narr",x:"我盯着你。声音有点发紧。"},{t:"me",x:"我要你把她删了。现在，当着我的面。"},{t:"narr",x:"你没说话，把手机拿出来。"},{t:"narr",x:"我看着你的拇指在屏幕上停了一下，然后点下去。"},{t:"choice",q:"他删了。你看着他的手。",opts:[{x:"盯着屏幕，确认真的删掉了。",best:!0,reply:"你盯着那个空掉的对话框看了三秒。三秒里你什么都没想。"},{x:"把脸转开，不想看。",reply:"你转开脸。听见手机锁屏的「咔」一声。"},{x:"说一句「谢谢」。",reply:"你说完就觉得这两个字很怪。他也愣了一下。"}]},{t:"me",x:"等等。"},{t:"narr",x:"我抓住你的手腕，不让你把手机收回去。"},{t:"me",x:"电话呢？QQ呢？还有没有别的号？全都删，一个都别留。"},{t:"narr",x:"你把电话也拉黑了。"},{t:"narr",x:"我盯着屏幕看了好几秒，心里那口气才慢慢松下来。"},{t:"narr",x:"眼睛却酸得厉害。"},{t:"narr",x:"我把手机合上，推回你手里。"},{t:"narr",x:"然后伸手抱住你，脸埋在你肩上。"},{t:"me",x:"云狐，从现在开始，你没有前对象了。你只有我。"},{t:"narr",x:"你身上有一点风的味道。"},{t:"narr",x:"我靠了一会儿，心里还是知足了一点点。"},{t:"narr",x:"可我又贪心地想再问清楚。"},{t:"narr",x:"我从你肩上退开一点，看着你，手指还攥着你的衣角。"},{t:"choice",q:"最后一个问题，问不问。",opts:[{x:"「你跟她……到哪一步了？」",best:!0,reply:"你问出口的时候，自己先疼了一下。"},{x:"不问了。删了就够了。",reply:"你把这句话咽回去。咽下去的东西不会消失，只会往下沉。"},{x:"「算了，当我没问。」",reply:"你松了手。他反而看着你，等你说下去。"}]},{t:"narr",x:"你沉默了一下。"},{t:"say",who:"云狐",x:"……亲过，没了。"},{t:"me",x:"哦。"},{t:"narr",x:"我松开你的衣角，低头看着我们中间的地面。"},{t:"narr",x:"就两个字。我胸口还是像被什么扎了一下。"},{t:"narr",x:"明明知道你们谈那么久，不可能什么都没有。可听见了还是难受。"},{t:"narr",x:"过了一会儿，我才抬眼看你。"},{t:"me",x:"那现在呢……你还会想她吗？"},{t:"say",who:"云狐",x:"不会啊。"},{t:"narr",x:"你说得很快。可我还是在意。"},{t:"choice",q:"你压了很久的那些话，要不要全说出来。",opts:[{x:"全说出来。一句都不留。",best:!0,reply:"你听见自己的声音一点一点高起来，又一点一点低下去。"},{x:"只说一半。",reply:"你说到「我暗恋你大半年」就停了。剩下的一半在喉咙里。"},{x:"摇头，说「没事」。",reply:"你说没事。他伸手想碰你的脸，你躲开了。"}]},{t:"me",x:"你说不会，我就该信你。"},{t:"me",x:"可我还是会想——你们谈了那么久，你为她变成那样，我都看在眼里。"},{t:"me",x:"她好看、优秀，我不瞎。"},{t:"me",x:"我暗恋你大半年，看着你难受，什么都不能说。"},{t:"me",x:"你们分手那天，我甚至偷偷开心过……"},{t:"me",x:"我又觉得自己坏。"},{t:"me",x:"现在你在旁边，我还是怕。我不是想闹，我就是憋太久了。"},{t:"narr",x:"你没有立刻说话，只是把我抱住。"},{t:"say",who:"云狐",x:"宝宝……你说什么呢……我们怎么可能一次就分了啊……我这么喜欢你。"},{t:"narr",x:"我把脸埋在你肩上，闻到你外套上的味道。"},{t:"narr",x:"风从树上面下来，吹得我眼睛更酸。"},{t:"me",x:"（我信了。至少那一刻，我信了。）"},{t:"tip",x:"第一幕结束。你把该删的都让他删了，把该问的也问完了。可你心里那口气，只松了一半。"}]},{id:"m2",noPhoto:!0,title:"第二幕 · 过了两个月，怕",sub:"闺蜜说，先低头的肯定是我",tone:"red",beats:[{t:"scene",place:"还是那个地方",time:"十二月 · 傍晚",x:"天暗得比十月早了很多。"},{t:"narr",x:"后来又过了两个月。"},{t:"narr",x:"我们在一起六个月了，我却越来越怕。"},{t:"narr",x:"你回消息越来越慢，见面时也总是很累的样子。"},{t:"narr",x:"最近发生了一些事，你的状态明显不对。"},{t:"narr",x:"连我闺蜜都让我做好心理准备。"},{t:"me",x:"（做好什么准备？她没说完。我也没敢问。）"},{t:"narr",x:"那几天我翻了你以前发过的所有东西。"},{t:"narr",x:"从九月翻到十一月。翻到手指发酸。"},{t:"narr",x:"有一条是十月我们刚在一起的时候，你写「今天天气很好」。"},{t:"narr",x:"底下没有配图。"},{t:"me",x:"（好什么好。今天阴。）"},{t:"narr",x:"我把手机扣在桌上，扣了很久。"},{t:"narr",x:"闺蜜给我发消息，问我今天问不问。"},{t:"narr",x:"我回了一个字：问。"},{t:"choice",q:"出门前那十分钟。",opts:[{x:"换一件他喜欢的衣服。",reply:"你换了。站在镜子前面看了一会儿，又换回来了。"},{x:"一件都不换，抓起外套就走。",best:!0,reply:"你没照镜子。走到楼下才发现外套穿反了。"},{x:"坐在床边，想今天别去了。",reply:"你坐了八分钟。然后站起来，拿钥匙。"}]},{t:"narr",x:"今天叫你出来，我一路都在发抖。"},{t:"narr",x:"我没像以前那样跑过去抱你。"},{t:"narr",x:"只站在原地看着你。"},{t:"me",x:"云狐。你最近……是不是觉得累了？跟我在一起。"},{t:"narr",x:"你走过来，抱了我一下。"},{t:"narr",x:"比往常轻很多。"},{t:"say",who:"云狐",x:"……有一点吧。"},{t:"narr",x:"我耳朵嗡的一下。"},{t:"narr",x:"手都凉了。"},{t:"narr",x:"我没动，任你抱着。过了两秒才小声问。"},{t:"me",x:"是因为我太黏你了吗？……还是她？"},{t:"narr",x:"你不说话。"},{t:"narr",x:"比直接说「是」还让我难受。"},{t:"narr",x:"我从你怀里退开一点，抬头看你。"},{t:"me",x:"你说话啊。你这样……我会乱想。"},{t:"choice",q:"他开始沉默。你要不要逼他。",opts:[{x:"逼他。今天必须有个答案。",best:!0,reply:"你抓住他的手。抓得很紧，紧到指节发白。"},{x:"不逼。等他自己说。",reply:"你等了很久。风把两个人的头发都吹乱了，他还是没说。"},{x:"转移话题，问他吃饭了没有。",reply:"他愣了一下，说没吃。你说那就先去吃点。这句话谁都没当真。"}]},{t:"narr",x:"你终于开口。"},{t:"say",who:"云狐",x:"我感觉太累了……嗯……我们要不——"},{t:"me",x:"别说。"},{t:"narr",x:"我一下抓住你的手，抓得很紧。"},{t:"me",x:"云狐，你别说那个。"},{t:"me",x:"我哪里不好，我可以改……你别不要我。"},{t:"narr",x:"你看着我，没说话。"},{t:"narr",x:"只是轻轻抱了我一下。"},{t:"say",who:"云狐",x:"你别哭了……"},{t:"me",x:"你别光抱我。"},{t:"narr",x:"我抬头看你，眼泪掉下来。"},{t:"me",x:"你回答我。你还要不要我？"},{t:"narr",x:"你还是沉默。"},{t:"narr",x:"我松开你的衣服，往后退了半步。"},{t:"narr",x:"用手背胡乱擦了一下脸。"},{t:"me",x:"你连一句话都不肯给我吗？"},{t:"me",x:"你看着我，云狐。"},{t:"choice",q:"他还是不说话。你怎么办。",opts:[{x:"转身就走。",reply:"你走了三步。第二步的时候，脚步已经慢下来了。"},{x:"站在原地，不走。",best:!0,reply:"你不走。你就站在那里看着他，眼泪一直掉，也不擦。"},{x:"把话说完，说清楚。",reply:"你把从十月攒到现在的话，一口气全说了。他一句都没打断。"}]},{t:"narr",x:"你终于看着我。"},{t:"say",who:"云狐",x:"我……我们分开吧。"},{t:"say",who:"云狐",x:"我想了很久的。你以后有什么不愉快还可以说，好嘛。"},{t:"me",x:"想很久了……"},{t:"narr",x:"我重复了一遍。声音轻得不像自己的。"},{t:"me",x:"那你今天，为什么还抱我？"},{t:"say",who:"云狐",x:"我怕你很难受……但……但我知道肯定会这样……"},{t:"narr",x:"你递给我纸巾。"},{t:"narr",x:"我没接。只是看着你。"},{t:"choice",q:"纸巾在你面前。",opts:[{x:"接过来。",reply:"你接了。纸巾上有他身上那种洗衣液的味道。"},{x:"不接。",best:!0,reply:"你没接。你把两只手都插进外套口袋里，攥成拳。"},{x:"把纸巾打掉。",reply:"纸巾落在地上。谁都没有去捡。"}]},{t:"me",x:"你告诉我一句实话。"},{t:"me",x:"这六个月，你有没有真的喜欢过我？"},{t:"say",who:"云狐",x:"这是肯定的……只是我太累了，不想谈恋爱了。"},{t:"me",x:"跟我在一起……让你这么累吗？"},{t:"narr",x:"我吸了吸鼻子。"},{t:"me",x:"还是说，你只是不想跟我谈了？"},{t:"narr",x:"你低下头。"},{t:"say",who:"云狐",x:"我不会和任何人谈了。我现在内心已经变了。"},{t:"narr",x:"我心里突然好冷。"},{t:"me",x:"不会和任何人……是因为以前那件事吗？"},{t:"narr",x:"我向前一步，看着你。"},{t:"me",x:"你不是不想谈，你是还没好，对不对？"},{t:"narr",x:"你轻轻「嗯」了一声。"},{t:"choice",q:"他承认了。你心里那口气。",opts:[{x:"「那你为什么还要答应我？」",best:!0,reply:"你把这句话问出来的时候，声音已经不抖了。抖的是手。"},{x:"「那你现在好一点没有。」",reply:"你问完自己都愣了一下。这时候你还在问他好不好。"},{x:"什么都不说，抱住他。",reply:"你抱住他的时候，他的两只手是垂着的。"}]},{t:"me",x:"你明明没好，为什么还要来招惹我？"},{t:"narr",x:"你沉默了一会儿。"},{t:"say",who:"云狐",x:"对不起，时间不早了，你还有什么要说的吗？"},{t:"tip",x:"第二幕结束。他提了分开。你没同意，也没反对 —— 你只是还在站着。"}]},{id:"m3",noPhoto:!0,title:"第三幕 · 走吧",sub:"风有点凉，我站在原地",tone:"gold",beats:[{t:"scene",place:"树下",time:"十二月 · 天已经黑了",x:"路灯亮起来，把两个人的影子拉得很长。"},{t:"narr",x:"「你还有什么要说的吗。」"},{t:"narr",x:"这句话在风里飘了两秒，才落下来。"},{t:"narr",x:"我看着你。"},{t:"narr",x:"你的头发被风吹开了一点，露出额头。"},{t:"me",x:"（我认识你大半年。见过你写题的样子、打球的样子、趴在桌上睡觉的样子。）"},{t:"me",x:"（我没见过你现在这个样子。）"},{t:"narr",x:"我把手从口袋里拿出来。"},{t:"choice",q:"他说「你还有什么要说的」。",opts:[{x:"「有。」",best:!0,reply:"你说有。然后一时想不出要说什么。"},{x:"「没有。」",reply:"你说没有。说完喉咙里像卡了一块东西。"},{x:"不回答，走过去。",reply:"你什么也没说，走到他面前停下。"}]},{t:"narr",x:"我走过去。"},{t:"narr",x:"最后抱了你一下。"},{t:"narr",x:"很轻。"},{t:"me",x:"你要好起来。"},{t:"narr",x:"你没有回抱我。"},{t:"narr",x:"我等了三秒。"},{t:"narr",x:"然后松开你，退开一步。"},{t:"choice",q:"退开之后，还要不要再说点什么。",opts:[{x:"「你要记得我。」",reply:"你把这句话说出来，声音很小。他不确定自己有没有听清。"},{x:"「别去找她。」",reply:"你说完就后悔了。可是话已经出去了，收不回来。"},{x:"什么都不说。",best:!0,reply:"你什么都没说。有些话说出来，就是给他留一条回来的路。"}]},{t:"narr",x:"我努力让自己看起来没那么狼狈。"},{t:"narr",x:"把外套的拉链拉到最上面，把下巴埋进去。"},{t:"me",x:"走吧。"},{t:"narr",x:"你先走。走了几步，没有回头。"},{t:"narr",x:"我在原地站着。"},{t:"narr",x:"看着你的背影被路灯一段一段照亮，又一段一段暗下去。"},{t:"narr",x:"我没有再回头，也没敢看你走远。"},{t:"narr",x:"风有点凉。"},{t:"narr",x:"我站在原地，忽然觉得十月的天，怎么这么冷。"},{t:"choice",q:"他走远以后。",opts:[{x:"走回家，一路上什么都没想。",best:!0,reply:"你走了四十分钟。到家门口才发现，手机一直在口袋里震。"},{x:"坐在原地，坐了很久。",reply:"你坐下。树很冷，石头也很冷。你坐到腿麻了才站起来。"},{x:"掏出手机，把他的对话框调到最上面。",reply:"你点开，又退出来。点开，又退出来。来来回回七次。"}]},{t:"narr",x:"后来我删了很多东西。"},{t:"narr",x:"聊天记录、照片、一起走过的那条路。"},{t:"narr",x:"删到最后，只剩一个空的对话框，上面写着「对方已不是你的好友」。"},{t:"narr",x:"我盯着那行字看了很久。"},{t:"me",x:"（他删我的时候，也是这样一下吗。）"},{t:"narr",x:"那几天我没去上晚自习。"},{t:"narr",x:"家里问我怎么了，我说没事，作业多。"},{t:"narr",x:"闺蜜给我发消息，我隔六个小时才回。"},{t:"narr",x:"她问我恨不恨你。"},{t:"choice",q:"你恨他吗。",opts:[{x:"「不恨。」",best:!0,reply:"你说不恨。她隔了很久回了一个「嗯」。"},{x:"「恨。」",reply:"你说恨。可你说完，眼泪先掉了下来。"},{x:"「我不知道。」",reply:"你说不知道。这三个字是这整件事里最真实的一句。"}]},{t:"narr",x:"后来我想明白了一件事。"},{t:"narr",x:"我从来没怪过他没好透。"},{t:"narr",x:"我怪的是他明明没好透，还伸手来牵我。"},{t:"narr",x:"第二天我还是去了学校。"},{t:"narr",x:"早读的铃响了三次，我一次都没听见。"},{t:"narr",x:"同桌推我，说老师点你名。"},{t:"narr",x:"我站起来，站了很久，说了一句「不会」。"},{t:"narr",x:"全班笑了。我也跟着笑了一下。"},{t:"narr",x:"坐下的时候，我在草稿纸角上写了一行字。"},{t:"narr",x:"「十月的天，怎么这么冷。」"},{t:"narr",x:"写完，把那个角撕掉了。"},{t:"choice",q:"最后一个问题。",opts:[{x:"如果重来一次，还会去问他吗。",best:!0,reply:"会。你想了三秒就答了。三秒里你甚至没有犹豫。"},{x:"如果重来一次，会在十月就放手吗。",reply:"不会。你在心里回答得很快，快到有点难过。"},{x:"不知道。",reply:"你不知道。这一次你允许自己不知道。"}]},{t:"narr",x:"再后来的事，没什么好说的。"},{t:"narr",x:"他后来考去了别的城市。我留在杭州。"},{t:"narr",x:"有一次在西子湖边走过，看见一个背影很像他。"},{t:"narr",x:"我停下来看了一眼。"},{t:"narr",x:"不是。"},{t:"narr",x:"我继续往前走。"},{t:"tip",x:"主线结束。这条线没有 S 评价 —— 它只是一段真的发生过的事。"}]}],m={id:"main",name:"主线 · 十月",icon:"🌧",tone:"blue",role:"第一人称 · 校外",line:"我明明想了一路狠话，一看见你，心先软了一半。",desc:"十月，高二。我们不在一个学校。你有一个前女友，你们分手五个多月了。",photo:"",tags:["主线","校外","无最优解"],noPhoto:!0},w=s;function u(){let r=0,x=0;for(const t of s)r+=(t.beats||[]).length,x+=(t.beats||[]).filter(a=>a.t==="choice").length;return{chapters:s.length,beats:r,choices:x}}const b=[{id:"shen",name:"沈砚",icon:"🩸",tone:"red",role:"纪检委员 · 查恋队队长",line:"她把每一条规矩都记得很熟，包括那些没写下来的。",desc:"高二（3）班，左臂永远别着红袖章。手里那本黑色硬壳本子记满了名字，也记了几页空行。",photo:"campus-day",tags:["外冷内热","规矩","记录"]},{id:"lin",name:"林晚",icon:"🎨",tone:"pink",role:"转学生 · 美术社",line:"她画所有人，唯独不画自己。",desc:"九月转来，坐在靠窗最后一排。课桌里永远有半截炭笔和一张没画完的速写。",photo:"cosplay",tags:["安静","画画","慢热"]},{id:"su",name:"苏念",icon:"📻",tone:"gold",role:"广播站站长",line:"整座学校都听过她的声音，很少有人见过她。",desc:"每天午休 12:20，广播里那句「这里是西子之声」就是她。下了播音台，她话少得出奇。",photo:"stage",tags:["声音","话密","台前台后"]},{id:"gu",name:"顾青",icon:"🧪",tone:"blue",role:"竞赛生 · 物理组",line:"她讲题的时候不看你，讲完才抬头。",desc:"年级前五，竞赛教室常驻。说话像在写解题步骤，一句多余的话都没有。",photo:"campus-aerial",tags:["理性","毒舌","竞赛"]}],n=[{id:"S",pct:.62,abs:30,label:"S · 留在光里",color:"#e6b95c"},{id:"A",pct:.44,abs:22,label:"A · 差一点说出口",color:"#f08bb0"},{id:"B",pct:.26,abs:14,label:"B · 同学关系",color:"#6aa9ff"},{id:"C",pct:0,abs:0,label:"C · 没有下文",color:"#8a94a2"}],p={shen:h,lin:l,su:c,gu:i};function y(r){if(r==="main")return 0;const x=p[r]||[];let t=0;for(const a of x)for(const e of a.beats||[]){if(e.t!=="choice")continue;const o=(e.opts||[]).find(f=>f.best);o&&(t+=Number(o.aff||0))}return t}function q(r){const x=r==="main"?s:p[r]||[];let t=0,a=0;for(const e of x)t+=(e.beats||[]).length,a+=(e.beats||[]).filter(o=>o.t==="choice").length;return{chapters:x.length,beats:t,choices:a,maxAff:y(r)}}function d(r,x){const t=Number(r)||0;if(x){const a=y(x);if(a>0){const e=t/a;return n.find(o=>e>=o.pct)||n[n.length-1]}}return n.find(a=>t>=a.abs)||n[n.length-1]}function g(r){const x=y(r)||1;return n.map(t=>({...t,min:Math.ceil(x*t.pct)}))}const S={id:"p0",title:"序 · 补课日的早晨",sub:"十月四日，周日，6:10",photo:"gate",beats:[{t:"scene",photo:"gate",place:"校门口",time:"6:10",x:"补课日的早晨，校门口的梧桐叶落了一地。"},{t:"narr",x:"七天的假期被砍成三天。今天是补课日，校门口的水泥地还留着昨夜的潮气。"},{t:"narr",x:"保安在门房里打哈欠，把铁栅栏推开一半。你低头看了一眼手机：6:10，比规定的起床铃早五分钟。"},{t:"me",x:"（早到五分钟，能多睡五分钟的地方已经没了。）"},{t:"say",who:"值周老师",x:"校牌戴好。走读的往这边，住宿的走那边。"},{t:"narr",x:"你从人群里挤过去。前面有人掉了东西，一张折了两折的纸，被风推到你脚边。"},{t:"choice",q:"那张纸是捡还是不捡。",opts:[{x:"捡起来，追上去还给他。",aff:2,flag:"kind",best:!0,reply:"你追了两步，把纸递过去。对方愣了一下，说了声谢谢，声音很轻。"},{x:"假装没看见，继续走。",aff:0,reply:"你从纸上跨过去。风把它吹进了下水口的格栅。"},{x:"捡起来，先看看是什么。",aff:1,flag:"curious",reply:"是一张座位表，右下角用铅笔写了一行很小的字：「别坐第三排。」"}]},{t:"narr",x:"教学楼在晨光里立着，三楼的窗户一扇一扇亮起来。你走上楼梯，鞋底和新拖过的地面摩擦，发出很轻的声响。"},{t:"tip",x:"主线开始。四个人的故事，会从不同的地方找上你。"}]},A={shen:{S:"高三毕业那天，她把那本黑色硬壳本子留在了纪检办公室的抽屉里。本子最后一页多了一行新的字：「已退出。已有人接。」你问她接下来去哪，她说：「跟你顺路。」",A:"后来她真的退了纪检。你们偶尔在走廊遇见，她会停下来说两句，说完就走。那本本子她一直没还给你。毕业照上，她站在你斜后方，袖子上什么都没有。",B:"她退了纪检，但你们没再走近。很多年后同学聚会，有人说沈砚去做了律师。你想起她记名字的样子，觉得挺合适。",C:"她退出了纪检，也退出了你的生活。那本本子最后被交到了年级组，锁在一个铁皮柜里。"},lin:{S:"毕业展上，最中间那张画换了。画的是天台，两个人并排坐着，都画了正面。右下角写着：「这次眼睛画好了。」她站在你旁边，很小声地说：「因为看了很多次。」",A:"她考去了美院。走之前送了你一张画，还是背影，但这次旁边多了一只伸过来的手。画的背面写着：「下次画正面。」",B:"她把那张画挂在了社团展上，后来被学校收进了走廊。你每次路过都会停一下，画上的人始终没有脸。",C:"她转学走了，没留下联系方式。画本里那张你的速写，最后也不知道去了哪里。"},su:{S:"最后一期节目，她没有念稿。她说：「这里是西子之声。我是苏念。我要谢谢一个人，他每次都走最后，所以我每次都能看见他。」然后她把话筒关掉，转头对你说：「现在，你走前面。」",A:"广播站换了新站长。她偶尔还会回来，坐在调音台后面听别人播。你推门进去，她就摘下一只耳机递给你，什么也不说。",B:"高三以后她不再播音。午休的喇叭里换了另一个人的声音，你还是会下意识抬头听第一句。",C:"她毕业了。广播站的门上换了新的排班表，没有她的名字。"},gu:{S:"一年后，集训队名单上出现了你的名字。她站在名单前，还是那副没什么表情的样子，只说了一句：「慢了四个月。」然后伸手，把你的名字那一行抹平。",A:"她去了北边。你们偶尔发消息，内容基本都是题。她最后一条写的是：「第三题，你现在敢写了。」",B:"保送之后她很少回学校。竞赛教室的桌上换了一批人，那本一千两百道题的错题本不知道被谁收走了。",C:"她走了以后，402 的灯还是每晚亮着，只是坐在第一排的人换了。"}};export{A as E,b as H,m as M,S as P,p as S,w as a,g as b,n as c,u as m,q as s,d as t};
